class Arco
{
    public int peso;
    public int aponta;

    public Arco(int p, int a)
    {
        peso = p;
        aponta = a;
    }
}

class Vertex
{
    public LinkedList<Arco> arestas;

    public Vertex()
    {
        arestas = new LinkedList<Arco>();
    }
}

class Grafo
{
    public int sizeV;
    public int sizeA;
    public Vertex[] vertex;
    public int[] visitado;

    public Grafo(int tamanho)
    {
        sizeV = tamanho;
        vertex = new Vertex[tamanho];
        visitado = new int[tamanho];
        for (int i = 0; i < tamanho; i++)
        {
            vertex[i] = new Vertex();
            visitado[i] = 0;
        }
    }

    public void AddArco(int were, int p, int a)
    {
        vertex[were].arestas.AddLast(new Arco(p, a));
        sizeA++;
    }

    public int Vertices()
    {
        return sizeV;
    }

    public int Arcos()
    {
        return sizeA;
    }
}

class Sociologia
{
    static Stack<int> fexado = new Stack<int>();

    static void DFS(Grafo xpto, int v)
    {
        xpto.visitado[v] = 1;
        LinkedListNode<Arco> iterador = xpto.vertex[v].arestas.First;
        while (iterador != null)
        {
            int aux = iterador.Value.aponta;
            if (xpto.visitado[aux] == 0)
                DFS(xpto, aux);
            iterador = iterador.Next;
        }
        fexado.Push(v);
    }

    static int DFS1(Grafo xpto, int v)
    {
        xpto.visitado[v] = 1;
        LinkedListNode<Arco> iterador = xpto.vertex[v].arestas.First;
        int count = 1;
        while (iterador != null)
        {
            int aux = iterador.Value.aponta;
            if (xpto.visitado[aux] == 0)
                count += DFS1(xpto, aux);
            iterador = iterador.Next;
        }
        return count;
    }

    public static void Main(string[] Args)
    {
        InputScanner ler = new InputScanner();
        StringBuilder output = new StringBuilder();
        int casos = ler.NextInt();
        for (int lim = 0; lim < casos; lim++)
        {
            int npessoas = ler.NextInt();
            Grafo amigos = new Grafo(npessoas);
            Grafo amigos1 = new Grafo(npessoas);
            for (int i = 0; i < npessoas; i++)
            {
                int amigo = ler.NextInt();
                int namigos = ler.NextInt();
                for (int x = 0; x < namigos; x++)
                {
                    int amig = ler.NextInt();
                    amigos.AddArco(amigo - 1, 0, amig - 1);
                    amigos1.AddArco(amig - 1, 0, amigo - 1);
                }
            }
            for (int i = 0; i < amigos.sizeV; i++)
                if (amigos.visitado[i] == 0)
                    DFS(amigos, i);
            output.Append("Caso #" + (lim + 1) + "\n");
            int grupos = 0;
            int solos = 0;
            while (fexado.Count > 0)
            {
                int aux = fexado.Pop();
                if (amigos1.visitado[aux] == 0)
                {
                    int count = DFS1(amigos1, aux);
                    if (count >= 4)
                        grupos++;
                    else
                        solos += count;
                }
            }
            output.Append(grupos + " " + solos + "\n");
        }
        Console.Write(output);
        ler.Close();
    }
}

