public class Prob21
{
    static double INF = 99999999.0;

    static void Main()
    {
        var stdin = new Scanner();
        double[,] p = new double[101, 101];
        double[] ax = new double[101];
        double[] ay = new double[101];
        double[] dis = new double[101];
        bool[] used = new bool[101];
        int n;
        n = stdin.NextInt();
        for (int i = 0; i < n; i++)
        {
            ax[i] = stdin.NextDouble();
            ay[i] = stdin.NextDouble();
        }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                p[i, j] = INF;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
            {
                double v = (ax[i] - ax[j]) * (ax[i] - ax[j]) + (ay[i] - ay[j]) * (ay[i] - ay[j]);
                v = Math.Sqrt(v);
                if (v < p[i, j])
                    p[i, j] = p[j, i] = v;
            }
        for (int i = 0; i < n; i++)
            dis[i] = p[0, i];
        Array.Fill(used, false);
        dis[0] = 0;
        used[0] = true;
        double ans = 0;
        for (int i = 0; i < n - 1; i++)
        {
            double min = INF;
            int tag = -1;
            for (int j = 1; j < n; j++)
            {
                if (!used[j] && dis[j] < min)
                {
                    min = dis[j];
                    tag = j;
                }
            }
            used[tag] = true;
            ans += min;
            for (int j = 1; j < n; j++)
            {
                if (!used[j] && dis[j] > p[tag, j])
                    dis[j] = p[tag, j];
            }
        }
        Console.WriteLine(ans.ToString("F2", CultureInfo.InvariantCulture));
    }
}

