public class Problema21
{
    public static float cont = 0;
    public static PriorityQueue<Aresta> heap = new PriorityQueue<Aresta>();
    public static No[] no = new No[100];
    public static void Main(string[] args)
    {
        Scanner input = new Scanner();
        int n = input.NextInt();
        for (int i = 0; i < n; i++)
        {
            no[i] = new No(input.NextDouble(), input.NextDouble());
        }
        prim(no[0], n);
        Console.Write(cont.ToString("F2", CultureInfo.InvariantCulture));
        Console.WriteLine();
    }
    public static void prim(No x, int numnos)
    {
        x.visitado = true;
        for (int i = 0; i < numnos; i++)
        {
            if (!no[i].visitado)
            {
                Aresta temp = new Aresta(x, no[i]);
                heap.Add(temp);
            }
        }
        while (heap.Size() != 0 && numnos > 0)
        {
            Aresta temp = heap.Peek();
            if (temp.b.visitado)
            {
                Aresta pl = heap.RemoveHead();
            }
            else
            {
                cont += temp.distancia;
                Aresta pl = heap.RemoveHead();
                numnos--;
                prim(temp.b, numnos);
            }
        }
    }
}

