class Aresta : IComparable<Aresta>
{
    public No a, b;
    public double distancia;
    public Aresta()
    {
    }
    public Aresta(No x, No y)
    {
        a = x;
        b = y;
        double dis1 = (a.x - b.x);
        double dis2 = (a.y - b.y);
        dis1 = dis1 * dis1;
        dis2 = dis2 * dis2;
        distancia = Math.Sqrt(dis1 + dis2);
    }
    public int CompareTo(Aresta x)
    {
        return this.distancia.CompareTo(x.distancia);
    }
}

class PriorityQueue<T> where T : IComparable<T>
{
    private List<T> heap = new List<T>();
    public bool IsEmpty()
    {
        return heap.Count == 0;
    }
    public int Size()
    {
        return heap.Count;
    }
    public T Peek()
    {
        return heap[0];
    }
    public void Add(T item)
    {
        heap.Add(item);
        SiftUp(heap.Count - 1);
    }
    public T RemoveHead()
    {
        T head = heap[0];
        T last = heap[heap.Count - 1];
        heap.RemoveAt(heap.Count - 1);
        if (heap.Count > 0)
        {
            heap[0] = last;
            SiftDown(0);
        }
        return head;
    }
    private void SiftUp(int i)
    {
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (heap[i].CompareTo(heap[parent]) < 0)
            {
                T tmp = heap[i];
                heap[i] = heap[parent];
                heap[parent] = tmp;
                i = parent;
            }
            else
            {
                break;
            }
        }
    }
    private void SiftDown(int i)
    {
        int n = heap.Count;
        while (true)
        {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = i;
            if (left < n && heap[left].CompareTo(heap[smallest]) < 0)
                smallest = left;
            if (right < n && heap[right].CompareTo(heap[smallest]) < 0)
                smallest = right;
            if (smallest == i)
                break;
            T tmp = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = tmp;
            i = smallest;
        }
    }
}

