public class Twentyfour
{
    public static void Prim(Graf g, No r)
    {
        r.Dist = 0;
        var q = new List<No>();
        var caminho = new List<No>();
        foreach (No n in g.V)
            q.Add(n);
        caminho.Add(r);
        while (q.Count != 0)
        {
            int index = Extrair(q, caminho);
            No u = q[index - 1];
            q.RemoveAt(index - 1);
            foreach (No adj in caminho)
                if (!ReferenceEquals(adj, u))
                {
                    double dist = Math.Sqrt(((adj.X - u.X) * (adj.X - u.X)) + ((adj.Y - u.Y) * (adj.Y - u.Y)));
                    if (dist < u.Dist)
                    {
                        u.Dist = dist;
                        u.Pai = u;
                    }
                }
            caminho.Add(u);
        }
    }

    private static int Extrair(List<No> q, List<No> cam)
    {
        double dist = 99999999.0;
        int i = 0;
        int index = i;
        foreach (No q2 in q)
        {
            i++;
            foreach (No cami in cam)
            {
                double dist2 = Math.Sqrt(((cami.X - q2.X) * (cami.X - q2.X)) + ((cami.Y - q2.Y) * (cami.Y - q2.Y)));
                if (dist2 < dist)
                {
                    dist = dist2;
                    index = i;
                }
            }
        }
        return index;
    }

    static void Main(string[] args)
    {
        Scanner scanner = new Scanner();
        int n = scanner.NextInt();
        double count = 0;
        Graf g = new Graf();
        for (int i = 0; i < n; i++)
        {
            g.V.Add(new No(scanner.NextDouble(), scanner.NextDouble()));
        }
        Prim(g, g.V[0]);
        for (int i = 0; i < n; i++)
            if (!g.V[i].Uspai)
            {
                count += g.V[i].Dist;
                g.V[i].Uspai = true;
            }
        Console.Out.WriteLine(string.Format(System.Globalization.CultureInfo.InvariantCulture, "{0:F2}", count));
    }
}

