class Ponto
{
    public double X;
    public double Y;
    public Ponto(double a, double b)
    {
        X = a;
        Y = b;
    }
    public double Distancia(Ponto p2)
    {
        double dist;
        dist = Math.Sqrt(Math.Pow(X - p2.X, 2) + Math.Pow(Y - p2.Y, 2));
        return dist;
    }
}

public class Prob24
{
    static Ponto[] array;
    static double[][] matrix;
    static double[][] dist;
    static int n;
    static bool[] visited;

    static void Prim(int r)
    {
        for (int i = 1; i <= n; i++)
        {
            dist[r][i] = double.MaxValue - 1;
        }
        dist[r][r] = 0;
        int vis = 1;
        while (vis != n)
        {
            int u = -1;
            double distmax = double.MaxValue;
            for (int i = 1; i < n + 1; i++)
            {
                if (!visited[i] && dist[r][i] < distmax)
                {
                    distmax = dist[r][i];
                    u = i;
                }
            }
            if (u == -1)
                break;
            visited[u] = true;
            vis++;
            for (int i = 1; i < n + 1; i++)
            {
                if (!visited[i] && matrix[u][i] < dist[r][i])
                {
                    dist[r][i] = matrix[u][i];
                }
            }
        }
    }

    static void Main()
    {
        double aux1 = 0.0;
        double aux2 = 0.0;
        double sum = 0.0;
        var s = new Scanner();
        n = s.NextInt();
        array = new Ponto[2 * n];
        matrix = new double[n + 1][];
        dist = new double[n + 1][];
        for (int i = 0; i < n + 1; i++)
        {
            matrix[i] = new double[n + 1];
            dist[i] = new double[n + 1];
        }
        visited = new bool[n + 1];
        for (int i = 1; i < n + 1; i++)
        {
            aux1 = s.NextDouble();
            aux2 = s.NextDouble();
            array[i] = new Ponto(aux1, aux2);
        }
        for (int i = 1; i < n + 1; i++)
        {
            for (int j = 1; j < n + 1; j++)
            {
                matrix[i][j] = array[i].Distancia(array[j]);
            }
        }
        Prim(1);
        for (int i = 1; i < n + 1; i++)
        {
            sum += dist[1][i];
        }
        Console.WriteLine(sum.ToString("F2", CultureInfo.InvariantCulture));
    }
}

