class Pessoa
{
    public int Id;
    public int Namigos;
    public int[] Amigos;
    public int T;
    public bool Visitado;

    public Pessoa(int i)
    {
        Id = i;
        Visitado = false;
    }

    public Pessoa(int i, int n)
    {
        Id = i;
        Namigos = n;
        Amigos = new int[n];
        T = 0;
        Visitado = false;
    }

    public int Pos()
    {
        int p = 0;
        for (int i = 0; i < Amigos.Length; i++)
        {
            if (Amigos[i] != 0)
            {
                p++;
            }
        }
        return p;
    }
}

class Grafo
{
    public int Nos;
    public int Tempo;
    public Pessoa[] Ppl;
    public Pessoa[] Tppl;
    public int Ngrupos;
    public int Nelementos;
    public int Res;
    public int Visitados;

    public Grafo(int n)
    {
        Nos = n;
        Tempo = 0;
        Ppl = new Pessoa[n + 1];
        Tppl = new Pessoa[n + 1];
        Ngrupos = 0;
        Nelementos = 0;
        Res = 0;
        Visitados = 0;
    }

    public void Criar(Scanner kb)
    {
        for (int i = 1; i <= Nos; i++)
        {
            Ppl[i] = new Pessoa(i);
            Tppl[i] = new Pessoa(i, Nos);
        }
        for (int i = 0; i < Nos; i++)
        {
            int id = kb.NextInt();
            int nf = kb.NextInt();
            Pessoa nova = new Pessoa(id, nf);
            Ppl[id] = nova;
            for (int j = 0; j < nf; j++)
            {
                int f = kb.NextInt();
                Ppl[id].Amigos[j] = f;
            }
        }
    }

    public void Transpor()
    {
        for (int i = 1; i <= Nos; i++)
        {
            for (int j = 0; j < Ppl[i].Amigos.Length; j++)
            {
                int aux = Ppl[i].Amigos[j];
                int idx = Tppl[aux].Pos();
                Tppl[aux].Amigos[idx] = i;
            }
        }
    }

    public void Dfs()
    {
        for (int i = 1; i < Ppl.Length; i++)
        {
            if (Ppl[i].Visitado == false)
            {
                DfsVisit(i);
            }
        }
    }

    public void DfsVisit(int x)
    {
        if (Ppl[x].Visitado == false)
        {
            Ppl[x].Visitado = true;
            for (int j = 0; j < Ppl[x].Amigos.Length; j++)
            {
                DfsVisit(Ppl[x].Amigos[j]);
            }
            Tempo++;
            Ppl[x].T = Tempo;
        }
    }

    public int FindMax()
    {
        int max = -1;
        int indice = -1;
        for (int i = 1; i <= Nos; i++)
        {
            if (max < Ppl[i].T && Tppl[i].Visitado == false)
            {
                max = Ppl[i].T;
                indice = i;
            }
        }
        return indice;
    }

    public void DfsTVisit(int x)
    {
        if (Tppl[x].Visitado == false)
        {
            Tppl[x].Visitado = true;
            Visitados++;
            for (int j = 0; j < Tppl[x].Pos(); j++)
            {
                DfsTVisit(Tppl[x].Amigos[j]);
            }
            Nelementos++;
        }
    }

    public void DfsT()
    {
        while (Visitados < Nos)
        {
            int id = FindMax();
            if (Tppl[id].Visitado == false && id != -1)
            {
                Nelementos = 0;
                DfsTVisit(id);
                if (Nelementos >= 4)
                {
                    Ngrupos++;
                }
                else
                {
                    Res = Res + Nelementos;
                }
            }
        }
    }

    public void Print()
    {
        Console.WriteLine(Ngrupos + " " + Res);
    }
}

