{
    static double[][] matrix;
    static bool[][] visited;
    static double[] dist;
    static int[] pred;
    static int q;

    static void Main(string[] args)
    {
        Scanner scanner = new Scanner();
        int n = q = scanner.NextInt();
        matrix = new double[n][];
        visited = new bool[n][];
        dist = new double[n];
        pred = new int[n];
        double[][] coordinates = new double[n][];
        for (int i = 0; i < n; i++)
        {
            matrix[i] = new double[n];
            visited[i] = new bool[n];
            double x = scanner.NextDouble();
            double y = scanner.NextDouble();
            coordinates[i] = new double[] { x, y };
        }
        for (int i = 0; i < n; i++)
        {
            for (int j = i; j < n; j++)
            {
                if (i != j)
                {
                    matrix[j][i] = matrix[i][j] = Calc(coordinates[i][0], coordinates[j][0], coordinates[i][1], coordinates[j][1]);
                }
            }
        }
        Prim(matrix, 0);
        double sum = 0;
        for (int i = 0; i < n; i++)
        {
            sum += dist[i];
        }
        Console.Out.WriteLine(string.Format(System.Globalization.CultureInfo.InvariantCulture, "{0:F2}", sum));
    }

    private static double Calc(double xi, double xj, double yi, double yj)
    {
        return Math.Sqrt((xi - xj) * (xi - xj) + (yi - yj) * (yi - yj));
    }

    private static void Kruskall() {}

    private static void Prim(double[][] graph, int no)
    {
        int aux = q;
        var vertices = new LinkedList<int>();
        for (int i = 0; i < q; i++)
        {
            pred[i] = 0;
            dist[i] = double.MaxValue;
            vertices.AddLast(i);
        }
        dist[no] = 0;
        while (vertices.First != null)
        {
            int u = Min(vertices);
            for (int i = 0; i < q; i++)
            {
                if (vertices.Contains(i) && graph[u][i] < dist[i])
                {
                    pred[i] = u;
                    dist[i] = graph[u][i];
                }
            }
        }
    }

    private static int Min(LinkedList<int> graph)
    {
        double min = double.MaxValue;
        int index = 0;
        foreach (int i in graph)
        {
            if (dist[i] < min)
            {
                index = i;
                min = dist[i];
            }
        }
        graph.Remove(index);
        return index;
    }

    private static void Print()
    {
        for (int i = 0; i < q; i++)
        {
            Console.Out.Write(dist[i] + " ");
        }
        Console.Out.WriteLine();
        for (int i = 0; i < q; i++)
        {
            Console.Out.Write(pred[i] + " ");
        }
    }
}

