class Freckles
{
    static int rank = 0;

    static void Main(string[] args)
    {
        Scanner stdin = new Scanner();
        int n = stdin.NextInt();
        Point[] faceMap = new Point[n];
        for (int i = 0; i < n; i++)
        {
            faceMap[i] = new Point(stdin.NextDouble(), stdin.NextDouble());
        }
        DrawOnHisFace(faceMap, n);
    }

    static void DrawOnHisFace(Point[] face, int n)
    {
        int groups = n;
        var links = new List<Link>();
        for (int i = 0; i < n - 1; i++)
        {
            for (int i2 = i + 1; i2 < n; i2++)
                links.Add(new Link(i, i2, Distance(face[i], face[i2])));
        }
        double total = 0;
        while (links.Count != 0 && groups != 1)
        {
            links.Sort();
            Link first = links[0];
            links.RemoveAt(0);
            Point a = face[first.A];
            Point b = face[first.B];
            rank = 0;
            Point parentA = a.FindParent();
            int rankA = rank;
            rank = 0;
            Point parentB = b.FindParent();
            int rankB = rank;
            if (!ReferenceEquals(parentA, parentB))
            {
                if (rankA > rankB)
                    parentA.UniteRoots(parentB);
                else
                    parentB.UniteRoots(parentA);
                groups--;
                total += first.D;
            }
        }
        Console.Out.WriteLine(string.Format(System.Globalization.CultureInfo.InvariantCulture, "{0:F2}", total));
    }

    static double Distance(Point a, Point b)
    {
        double x = Math.Abs(a.X - b.X);
        double y = Math.Abs(a.Y - b.Y);
        return Math.Sqrt((x * x) + (y * y));
    }
}

class Point
{
    public Point Prev;
    public double X;
    public double Y;

    public Point(double x, double y)
    {
        Prev = this;
        X = x;
        Y = y;
    }

    public int CompareTo(Point a)
    {
        if (a.X == X && a.Y == Y)
            return 0;
        else if (a.X > X)
            return -1;
        else
            return 1;
    }

    public Point FindParent()
    {
        if (Prev == this)
            return this;
        else
        {
            Freckles.rank++;
            Prev = Prev.FindParent();
        }
        if (Prev != this)
        {
            Freckles.rank++;
            Point parent = Prev.FindParent();
            Prev = parent;
            return parent;
        }
        return this;
    }

    public void UniteRoots(Point a)
    {
        a.Prev = this;
    }
}

