public class Sociologo
{
    static int res1 = 0, res2 = 0;

    public static int DfsVisit(Grafo a, int val, int instante, int[] cor, int[] posnum)
    {
        cor[val] = 1;
        while (a.Verts[val].Adjs.Count != 0)
        {
            int analisa = a.Verts[val].Adjs.First.Value;
            a.Verts[val].Adjs.RemoveFirst();
            if (cor[analisa] == 0)
                instante = DfsVisit(a, analisa, instante, cor, posnum);
        }
        instante++;
        posnum[val] = instante;
        return instante;
    }

    public static void Dfs(Grafo a, int n, Stack<int> v, int[] posnum)
    {
        int instante = 0;
        int[] prev = new int[n];
        for (int i = 1; i < n; i++)
            prev[i] = int.MaxValue;
        int[] cor = new int[n];
        while (v.Count != 0)
        {
            int val = v.Pop();
            if (cor[val] == 0)
                instante = DfsVisit(a, val, instante, cor, posnum);
        }
    }

    public static int DfsnVisit(Grafo a, int val, int instante, int[] cor)
    {
        cor[val] = 1;
        while (a.Verts[val].Adjs.Count != 0)
        {
            int analisa = a.Verts[val].Adjs.First.Value;
            a.Verts[val].Adjs.RemoveFirst();
            if (cor[analisa] == 0)
                instante = DfsnVisit(a, analisa, instante, cor);
        }
        instante++;
        return instante;
    }

    public static void Dfsn(Grafo a, int n, Stack<int> v)
    {
        int instante = 0;
        int[] prev = new int[n];
        for (int i = 1; i < n; i++)
            prev[i] = int.MaxValue;
        int[] cor = new int[n];
        while (v.Count != 0)
        {
            instante = 0;
            int val = v.Pop();
            if (cor[val] == 0)
            {
                instante = DfsnVisit(a, val, instante, cor);
                if (instante >= 4)
                    res1++;
                else
                    res2 += instante;
            }
        }
    }

    public static void Main(string[] args)
    {
        Scanner io = new Scanner();
        int testes = io.NextInt();
        Stack<int> pilha = new Stack<int>();
        for (int i = 1; i <= testes; i++)
        {
            int n = io.NextInt() + 1;
            Grafo a = new Grafo(n);
            Grafo b = new Grafo(n);
            for (int j = 1; j < n; j++)
            {
                int liga = io.NextInt();
                pilha.Push(liga);
                int nfilhos = io.NextInt();
                for (int t = 0; t < nfilhos; t++)
                {
                    int filho = io.NextInt();
                    a.Verts[liga].Adjs.AddFirst(filho);
                    b.Verts[filho].Adjs.AddFirst(liga);
                }
            }
            int[] posnum = new int[n];
            Dfs(a, n, pilha, posnum);
            for (int j = 1; j < n; j++)
            {
                for (int t = 1; t < n; t++)
                {
                    if (posnum[t] == j)
                        pilha.Push(t);
                }
            }
            Dfsn(b, n, pilha);
            Console.WriteLine("Caso #" + i);
            Console.WriteLine("" + res1 + " " + res2);
            res1 = 0;
            res2 = 0;
        }
    }
}

