        for (int i = 1; i <= n_pontos; i++)
            pontos[i] = new Node(stdin.NextDouble(), stdin.NextDouble(), i);
        for (int i = 1; i <= n_pontos; i++)
            for (int j = 1; j <= n_pontos; j++)
                dist[i][j] = CalcDist(pontos[i], pontos[j]);
