    }

    static double CalcDist(Node a, Node b)
    {
        double x_dist = (a.X - b.X) * (a.X - b.X);
        double y_dist = (a.Y - b.Y) * (a.Y - b.Y);
        return Math.Sqrt((x_dist + y_dist));
