class Grafo
{
    public VerticesAdj[] g;
    public VerticesAdj[] gT;
    public int nverts;
    public NGrupos ngrupos;
    private bool[] vvisitado;
    private Stack<int> decresT_final;
    private int n;

    public Grafo(int nv)
    {
        g = new VerticesAdj[nv + 1];
        gT = new VerticesAdj[nv + 1];
        for (int i = 1; i <= nv; i++)
        {
            g[i] = null;
            gT[i] = null;
        }
        nverts = nv;
        ngrupos = new NGrupos();
        vvisitado = new bool[nv + 1];
        for (int i = 1; i <= nv; i++)
            vvisitado[i] = false;
        decresT_final = new Stack<int>();
        n = 0;
    }

    public void InserirLigacao(int de, int para)
    {
        g[de] = new VerticesAdj(para, g[de]);
        gT[para] = new VerticesAdj(de, gT[para]);
    }

    public NGrupos NumeroGrupos()
    {
        DFS_G();
        DFS_GT_tfinal();
        return ngrupos;
    }

    public void DFS_G()
    {
        for (int i = 1; i <= nverts; i++)
            if (!vvisitado[i])
                DFS_Gvisit(i);
    }

    private void DFS_Gvisit(int v)
    {
        vvisitado[v] = true;
        for (VerticesAdj p = g[v]; p != null; p = p.prox)
            if (!vvisitado[p.vertice])
                DFS_Gvisit(p.vertice);
        decresT_final.Push(v);
    }

    public void DFS_GT_tfinal()
    {
        for (int i = 1; i <= nverts; i++)
            vvisitado[i] = false;
        while (decresT_final.Count > 0)
        {
            int v = decresT_final.Pop();
            if (!vvisitado[v])
            {
                DFS_GTvisit(v);
                if (n < 4)
                    ngrupos.npmenor4 += n;
                else
                    ngrupos.apartir4++;
                n = 0;
            }
        }
    }

    private void DFS_GTvisit(int v)
    {
        vvisitado[v] = true;
        for (VerticesAdj p = gT[v]; p != null; p = p.prox)
            if (!vvisitado[p.vertice])
                DFS_GTvisit(p.vertice);
        n++;
    }
}

