class Graph
{
    public LinkedList<Node> nodes;
    public double ink;
    public Graph()
    {
        nodes = new LinkedList<Node>();
        ink = 0.0;
    }
    public void AddNode(Node a)
    {
        nodes.AddLast(a);
    }
    public void Populate()
    {
        LinkedList<Node> temp = new LinkedList<Node>();
        foreach (Node n in nodes)
            temp.AddLast(n);
        Node parent;
        parent = temp.First.Value;
        temp.RemoveFirst();
        while (temp.Count > 0)
        {
            foreach (Node a in temp)
            {
                parent.AddEdge(MakeEdge(parent, a));
                a.AddEdge(MakeEdge(a, parent));
            }
            parent = temp.First.Value;
            temp.RemoveFirst();
        }
    }
    public Edge MakeEdge(Node a, Node b)
    {
        return new Edge(a, b);
    }
    public double Prim()
    {
        double aux = double.PositiveInfinity;
        LinkedList<Node> stuff = new LinkedList<Node>();
        foreach (Node n in nodes)
            stuff.AddLast(n);
        List<Edge> edges = new List<Edge>();
        Node node = null;
        Edge auxedge = null;
        node = stuff.First.Value;
        stuff.RemoveFirst();
        node.visited = true;
        while (stuff.Count > 0)
        {
            aux = double.PositiveInfinity;
            edges.AddRange(node.adj);
            foreach (Edge a in edges)
            {
                if (!(a.target.visited))
                {
                    if (aux > a.weight)
                    {
                        aux = a.weight;
                        auxedge = a;
                    }
                }
            }
            if (aux != double.PositiveInfinity)
            {
                ink += aux;
                auxedge.target.visited = true;
                Node target = auxedge.target;
                LinkedListNode<Node> cur = stuff.First;
                while (cur.Value != target)
                    cur = cur.Next;
                node = cur.Value;
                stuff.Remove(cur);
            }
        }
        return ink;
    }
}

class Edge
{
    public double weight;
    public Node target;
    public Node from;
    public Edge(Node from, Node target)
    {
        this.target = target;
        this.from = from;
        weight = Math.Sqrt(Math.Pow(from.x - target.x, 2) + Math.Pow(from.y - target.y, 2));
    }
}

