            for (int j = 0; j < nP; j++)
            {
                int y = scn.NextInt() - 1;
                AdjList[x].Add(y);
                AdjListT[y].Add(x);
            }
        }
    }

    public static void DFS1(int u)
    {
        foreach (int w in AdjList[u])
            if (colour[w] == 0)
            {
                colour[w] = 2;
                DFS1(w);
            }
        ftimes.AddFirst(u);
    }

    public static int DFS2(int u)
    {
        int lenSCC = 1;
        foreach (int w in AdjListT[u])
            if (colour[w] == 0)
            {
                colour[w] = 2;
                lenSCC += DFS2(w);
            }
        return lenSCC;
    }

