public class Sociologia
{
    private static Scanner stdin = new Scanner();
    private static int tempo;
    private static Stack<int> pilha = new Stack<int>();
    private static List<int> arvore = new List<int>();
    private static int grupos = 0;
    private static int sozinhos = 0;

    public static void Main(string[] args)
    {
        int ncasos = stdin.NextInt();
        for (int i = 1; i < ncasos + 1; i++)
        {
            int nalunos = stdin.NextInt();
            Vertice[] vertices = new Vertice[nalunos];
            vertices = RecolherDados(nalunos, vertices);
            vertices = Ordenar(vertices);
            vertices = Dfs(vertices);
            vertices = CalcularTransposta(vertices);
            DfsInvertido(vertices);
            Console.WriteLine("Caso #" + i + "\n" + grupos + " " + sozinhos);
        }
    }

    private static void DfsInvertido(Vertice[] vertices)
    {
        grupos = 0;
        sozinhos = 0;
        Vertice u;
        foreach (Vertice v in vertices)
        {
            v.Cor = 0;
        }
        while (pilha.Count != 0)
        {
            u = vertices[pilha.Pop() - 1];
            arvore = new List<int>();
            if (u.Cor == 0)
            {
                arvore.Add(u.Aluno);
                vertices = DfsVisitInvertido(u, vertices);
            }
            if (arvore.Count >= 4)
                grupos++;
            else
            {
                sozinhos = sozinhos + arvore.Count;
            }
        }
    }

    private static Vertice[] DfsVisitInvertido(Vertice v, Vertice[] vertices)
    {
        v.Cor = 1;
        foreach (int amigo in v.Tamigos)
        {
            if (vertices[amigo - 1].Cor == 0)
            {
                arvore.Add(amigo);
                vertices = DfsVisitInvertido(vertices[amigo - 1], vertices);
            }
        }
        return vertices;
    }

    private static Vertice[] CalcularTransposta(Vertice[] vertices)
    {
        foreach (Vertice v in vertices)
        {
            foreach (int aluno in v.Amigos)
            {
                vertices[aluno - 1].AdicionarAmigoTransposto(v.Aluno);
            }
        }
        return vertices;
    }

    private static Vertice[] Ordenar(Vertice[] vertices)
    {
        for (int i = 0; i < vertices.Length - 1; i++)
        {
            if (vertices[i + 1].Aluno < vertices[i].Aluno)
            {
                Vertice temp = vertices[i];
                vertices[i] = vertices[i + 1];
                vertices[i + 1] = temp;
            }
        }
        return vertices;
    }

    private static Vertice[] Dfs(Vertice[] vertices)
    {
        foreach (Vertice v in vertices)
        {
            v.Cor = 0;
            v.Tempo = 0;
        }
        tempo = 0;
        foreach (Vertice v in vertices)
        {
            if (v.Cor == 0)
            {
                vertices = DfsVisit(v, vertices);
            }
        }
        return vertices;
    }

    private static Vertice[] DfsVisit(Vertice v, Vertice[] vertices)
    {
        v.Cor = 1;
        tempo++;
        v.Tempo = tempo;
        foreach (int amigo in v.Amigos)
        {
            if (vertices[amigo - 1].Cor == 0)
            {
                vertices = DfsVisit(vertices[amigo - 1], vertices);
            }
        }
        tempo++;
        v.Tempo = tempo;
        pilha.Push(v.Aluno);
        return vertices;
    }

    private static Vertice[] RecolherDados(int nalunos, Vertice[] vertices)
    {
        for (int j = 0; j < nalunos; j++)
        {
            int id = stdin.NextInt();
            int namigos = stdin.NextInt();
            vertices[j] = new Vertice(id, namigos);
            for (int h = 0; h < namigos; h++)
            {
                vertices[j].AdicionaAmigo(stdin.NextInt());
            }
        }
        return vertices;
    }
}

