public class Prob21
{
    static void Main()
    {
        var stdin = new Scanner();
        int n = stdin.NextInt();
        var p = new Point[n];
        for (int i = 0; i < n; i++)
        {
            double a = stdin.NextDouble();
            double b = stdin.NextDouble();
            p[i] = new Point(a, b);
        }
        var pq = new PriorityQueue<Edge, double>();
        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                Edge edge = new Edge(i, j, p[i].X, p[i].Y, p[j].X, p[j].Y);
                pq.Enqueue(edge, edge.GetDistance());
            }
        }
        bool[] added = new bool[n];
        double total = 0;
        Edge temp = pq.Dequeue();
        added[temp.Node1] = true;
        added[temp.Node2] = true;
        total += temp.GetDistance();
        bool found = false;
        var tempList = new List<Edge>();
        while (pq.Count > 0 && !found)
        {
            Edge temp2 = pq.Dequeue();
            if ((added[temp2.Node1] && !added[temp2.Node2]) || (!added[temp2.Node1] && added[temp2.Node2]))
            {
                added[temp2.Node1] = true;
                added[temp2.Node2] = true;
                total += temp2.GetDistance();
                foreach (Edge e in tempList)
                    pq.Enqueue(e, e.GetDistance());
                tempList.Clear();
            }
            else if (!added[temp2.Node1] && !added[temp2.Node2])
                tempList.Add(temp2);
        }
        Console.WriteLine(total.ToString("F2", CultureInfo.InvariantCulture));
    }
}

