class Edge : IComparable<Edge>
{
    public Node A;
    public Node B;
    public double Dist;

    public Edge(Node a, Node b)
    {
        A = a;
        B = b;
        Dist = Math.Sqrt(Math.Pow(B.X - A.X, 2) + Math.Pow(B.Y - A.Y, 2));
    }

    public int CompareTo(Edge e)
    {
        if (Dist < e.Dist)
        {
            return -1;
        }
        else if (Dist > e.Dist)
        {
            return 1;
        }
        return 0;
    }
}

public class SardasKrustall
{
    public static List<Set> sets;
    public static List<Edge> aList;
    public static List<Edge> edges;

    public static int Find(Node node)
    {
        for (int i = 0; i < sets.Count; i++)
        {
            for (int j = 0; j < sets[i].Nodes.Count; j++)
            {
                if (sets[i].Nodes[j].X == node.X && sets[i].Nodes[j].Y == node.Y)
                {
                    return i;
                }
            }
        }
        return -1;
    }

    public static void Merge(int a, int b)
    {
        for (int i = 0; i < sets[b].Nodes.Count; i++)
        {
            sets[a].Nodes.Add(sets[b].Nodes[i]);
        }
        sets.RemoveAt(b);
    }

    public static void ResetId()
    {
        for (int i = 0; i < sets.Count; i++)
        {
            sets[i].Id = i;
        }
    }

    static void Main(string[] args)
    {
        Scanner input = new Scanner();
        Graph g = new Graph(input.NextInt());
        for (int i = 0; i < g.N; i++)
        {
            Node n = new Node(input.NextDouble(), input.NextDouble(), i);
            g.AddNode(n);
        }
        aList = new List<Edge>();
        edges = new List<Edge>();
        sets = new List<Set>();
        for (int i = 0; i < g.N; i++)
        {
            sets.Add(new Set(g.Nodes[i], i));
        }
        for (int i = 0; i < g.N; i++)
        {
            for (int j = i + 1; j < g.N; j++)
            {
                edges.Add(new Edge(g.Nodes[i], g.Nodes[j]));
            }
        }
        edges.Sort();
        foreach (Edge e in edges)
        {
            int a = Find(e.A);
            int b = Find(e.B);
            if (a != b)
            {
                aList.Add(e);
                Merge(a, b);
            }
        }
        double result = 0.0;
        foreach (Edge edge in aList)
        {
            result += edge.Dist;
        }
        Console.Out.WriteLine(string.Format(System.Globalization.CultureInfo.InvariantCulture, "{0:F2}", result));
    }
}

