class Graph
{
    int n;
    public Node[] nodes;
    public Graph(int n)
    {
        this.n = n;
        this.nodes = new Node[n + 1];
        for (int i = 1; i <= n; i++)
            nodes[i] = new Node();
    }
    public double Distance(Node a, Node b)
    {
        return Math.Sqrt(Math.Pow(a.x - b.x, 2) + Math.Pow(a.y - b.y, 2));
    }
    public void AddNode(int i, double a, double b)
    {
        this.nodes[i].x = a;
        this.nodes[i].y = b;
        this.nodes[i].visited = false;
    }
    public void Prim(int no)
    {
        nodes[no].dist = 0;
        double cost = 0;
        for (int i = 1; i <= n; i++)
        {
            double min = 1500;
            int minNode = 1500;
            for (int j = 1; j <= n; j++)
            {
                if (nodes[j].visited == false && nodes[j].dist < min)
                {
                    min = nodes[j].dist;
                    minNode = j;
                }
            }
            cost += min;
            nodes[minNode].visited = true;
            foreach (Aresta a in nodes[minNode].adj)
                if (!nodes[a.node].visited && a.weight < nodes[a.node].dist)
                    nodes[a.node].dist = a.weight;
        }
