class Graph
{
    public readonly int Dim = 1000;
    public LinkedList<int>[] Adj;
    public int[] Color;
    public int[] Parent;
    public int[] StartTime;
    public int[] FinishTime;
    public int Time;

    public Graph()
    {
        Adj = new LinkedList<int>[Dim];
        Color = new int[Dim];
        Parent = new int[Dim];
        StartTime = new int[Dim];
        FinishTime = new int[Dim];
    }

    public Graph Transpose()
    {
        Graph transposed = new Graph();
        for (int i = 0; this.Adj[i] != null; i++)
        {
            transposed.Adj[i] = new LinkedList<int>();
        }
        for (int i = 0; this.Adj[i] != null; i++)
        {
            foreach (int node in Adj[i])
            {
                transposed.Adj[node].AddLast(i);
            }
        }
        return transposed;
    }

    public void DepthFirstSearch(LinkedList<int> fst, LinkedList<int> snd)
    {
        for (int i = 0; i < Color.Length; i++)
        {
            Color[i] = 0;
            Parent[i] = -1;
            StartTime[i] = -1;
            FinishTime[i] = -1;
        }
        Time = 0;
        foreach (int source in fst)
        {
            if (Color[source] == 0)
            {
                DepthFirstVisit(source, snd);
            }
        }
    }

    public void DepthFirstVisit(int source, LinkedList<int> snd)
    {
        Color[source] = 1;
        Time += 1;
        StartTime[source] = Time;
        foreach (int node in Adj[source])
        {
            if (Color[node] == 0)
            {
                Parent[node] = source;
                DepthFirstVisit(node, snd);
            }
        }
        Color[source] = 2;
        Time += 1;
        FinishTime[source] = Time;
        snd.AddFirst(source);
    }

    public PriorityQueue<int, int> FindValues(int value, int[] vtr)
    {
        PriorityQueue<int, int> fila = new PriorityQueue<int, int>();
        for (int i = 0; Adj[i] != null; i++)
        {
            if (vtr[i] == value)
            {
                fila.Enqueue(i, i);
            }
        }
        return fila;
    }

    public void MakeTree(LinkedList<int> tree, int value)
    {
        if (value != -1)
        {
            tree.AddLast(value);
        }
        PriorityQueue<int, int> fila = new PriorityQueue<int, int>();
        fila = FindValues(value, Parent);
        while (fila.Count > 0)
        {
            int newValue = fila.Dequeue();
            MakeTree(tree, newValue);
        }
    }

    public LinkedList<int>[] BuildTreeForest()
    {
        LinkedList<int>[] tree = new LinkedList<int>[Dim];
        for (int i = 0; Adj[i] != null; i++)
        {
            if (Parent[i] == -1)
            {
                int aux = 0;
                for (int j = 0; tree[j] != null; j++)
                {
                    aux++;
                }
                tree[aux] = new LinkedList<int>();
                MakeTree(tree[aux], i);
            }
        }
        return tree;
    }
}

class Sociologia
{
