    }
}

class Grafo
{
    public Vertice[] Verts;
    public int Nverts, Narcos;

    public Grafo(int n)
    {
        Nverts = 0;
        Narcos = 0;
        Verts = new Vertice[n];
    }

    public void NovoVert(int n)
    {
        Verts[n] = new Vertice(n);
        Nverts++;
    }

    public void NovoAdj(int v, int a, int c)
    {
        if (ProcuraArco(v, a) == 0)
        {
            Verts[v].AdicionarAdj(a, c);
            Narcos++;
        }
    }

    public int ProcuraArco(int v, int d)
    {
        Arco aux = Verts[v].Adjs;
        while (aux != null)
        {
            if (aux.ProxVert == d)
                return 1;
            else
                aux = aux.Prox;
        }
        return 0;
    }
}

class Fila
{
    public Node First;
    public int Length;

    public Fila()
    {
        First = null;
        Length = 0;
    }

    public void PushNode(int v)
    {
        First = new Node(v, First);
        Length++;
    }

    public int PopNode()
    {
        int aux = First.Val;
        First = First.Prox;
        Length--;
        return aux;
    }

    public bool IsEmpty()
    {
        return Length == 0;
    }

    public class Node
    {
        public int Val;
        public Node Prox;

        public Node(int v, Node p)
        {
            Val = v;
            Prox = p;
        }
    }
}

class Set
{
    public int[] S;
    public int Size, Length;

    public Set(int x)
    {
        Size = x + 1;
        Length = 0;
        S = new int[x + 1];
        for (int i = 0; i < x + 1; i++)
            S[i] = 0;
    }

    public void Insert(int n)
    {
        S[n] = 1;
        Length++;
    }

    public void Remove(int n)
    {
        S[n] = 0;
        Length--;
    }

    public int Tamanho()
    {
        return Length;
    }

    public void Imprime()
    {
        for (int i = 1; i < Size; i++)
        {
            if (S[i] == 1)
                Console.WriteLine(i);
        }
    }

    public bool IsEqual(Set x)
    {
        if (Length != x.Length)
            return false;
        for (int i = 0; i < Size; i++)
            if (S[i] != x.S[i])
                return false;
        return true;
    }

    public Set Intersect(Set x)
    {
        Set aux = new Set(Size);
        for (int i = 0; i < Size; i++)
        {
            if (S[i] == 1 && x.S[i] == 1)
                aux.Insert(i);
        }
        return aux;
    }
}

class Lista
{
