    public int Length;

    public Lista()
    {
        First = null;
        Length = 0;
    }

    public void AddNode(Set n)
    {
        int flag;
        if (Length == 0)
        {
            First = new Node(n, null);
            Length++;
        }
        else
        {
            Node aux = First;
            flag = 0;
            while (aux != null)
            {
                if (aux.S.IsEqual(n))
                {
                    flag = 1;
                    break;
                }
                aux = aux.Prox;
            }
            if (flag == 0)
            {
                aux = new Node(n, First);
                First = aux;
                Length++;
            }
        }
    }

    public class Node
    {
