public class Sociologia
{
    static Set DepthFirstSearch(Grafo g, int v, int n)
    {
        int[] lidos = new int[n + 1];
        int i;
        Arco aux;
        Fila stack = new Fila();
        Set s = new Set(n + 1);
        for (i = 0; i < n + 1; i++)
            lidos[i] = 0;
        stack.PushNode(v);
        s.Insert(v);
        while (!stack.IsEmpty())
        {
            i = stack.PopNode();
            lidos[i] = 1;
            if (g.Verts[i] != null)
            {
                aux = g.Verts[i].Adjs;
                while (aux != null)
                {
                    if (lidos[aux.ProxVert] == 0)
                    {
                        stack.PushNode(aux.ProxVert);
                        lidos[aux.ProxVert] = 1;
                        s.Insert(aux.ProxVert);
                    }
                    aux = aux.Prox;
                }
            }
        }
        return s;
    }

    public static void Main(string[] args)
    {
        int ncasos, npessoas, i, j, n, aux, c;
        int[] grupo;
        Grafo g, trans;
        Set s1, s2, s;
        Scanner kb = new Scanner();
        Lista sets;
        ncasos = kb.NextInt();
        for (c = 0; c < ncasos; c++)
        {
            sets = new Lista();
            npessoas = kb.NextInt();
            aux = npessoas;
            g = new Grafo(npessoas + 1);
            trans = new Grafo(npessoas + 1);
            while (aux > 0)
            {
                i = kb.NextInt();
                g.NovoVert(i);
                j = kb.NextInt();
                while (j > 0)
                {
                    n = kb.NextInt();
                    g.NovoAdj(i, n, 0);
                    if (trans.Verts[n] == null)
                        trans.NovoVert(n);
                    trans.NovoAdj(n, i, 0);
                    j--;
                }
                aux--;
            }
            grupo = new int[npessoas + 1];
            for (i = 0; i <= npessoas; i++)
                grupo[i] = 0;
            for (i = 1; i <= npessoas; i++)
            {
                s1 = DepthFirstSearch(g, i, npessoas);
                s2 = DepthFirstSearch(trans, i, npessoas);
                s = s1.Intersect(s2);
                if (s.Length >= 4)
                {
                    sets.AddNode(s);
                    for (j = 1; j < s.Size; j++)
                    {
                        if (s.S[j] == 1)
                            grupo[j] = 1;
                    }
                }
            }
            j = 0;
            for (i = 1; i <= npessoas; i++)
            {
                if (grupo[i] == 0)
                    j++;
            }
            Console.WriteLine("Caso #" + (c + 1));
            Console.WriteLine(sets.Length + " " + j);
        }
    }
}

