class Prob24
{
    static int n;
    static int c;
    static double total = 0.00;
    static double[] key;
    static int[] parent;
    static bool[] vis;
    static bool[] vis2;

    static void Main(string[] args)
    {
        var lines = new List<string>();
        string line;
        while ((line = Console.In.ReadLine()) != null)
        {
            lines.Add(line);
        }
        n = int.Parse(lines[0]);
        double[][] a = new double[n][];
        double[][] dist = new double[n][];
        key = new double[n];
        parent = new int[n];
        vis = new bool[n];
        vis2 = new bool[n];
        var heap = new List<Heapi>();
        for (int i = 0; i < n; i++)
        {
            a[i] = new double[2];
            dist[i] = new double[n];
            string[] input = lines[i + 1].Split(' ');
            a[i][0] = double.Parse(input[0], System.Globalization.CultureInfo.InvariantCulture);
            a[i][1] = double.Parse(input[1], System.Globalization.CultureInfo.InvariantCulture);
        }
        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                double primeiro = (a[j][0] - a[i][0]) * (a[j][0] - a[i][0]);
                double segundo = (a[j][1] - a[i][1]) * (a[j][1] - a[i][1]);
                dist[i][j] = Math.Sqrt(primeiro + segundo);
                dist[j][i] = Math.Sqrt(primeiro + segundo);
            }
        }
        Prim(a, dist, heap, 0);
        string result = string.Format(System.Globalization.CultureInfo.InvariantCulture, "{0:F2}", total);
        Console.Out.WriteLine(result.Replace(",", "."));
    }

    static void Prim(double[][] a, double[][] dist, List<Heapi> heap, int x)
    {
        for (int i = 0; i < n; i++)
        {
            key[i] = double.PositiveInfinity;
            parent[i] = -1;
        }
        key[x] = 0.0;
        heap.Add(new Heapi(x, key[x]));
        while (heap.Count != 0)
        {
            heap.Sort((o1, o2) => o1.Valor.CompareTo(o2.Valor));
            Heapi s = heap[0];
            heap.RemoveAt(0);
            int u = s.Index;
            if (!vis[u])
            {
                vis[u] = true;
                total += key[u];
            }
            for (int i = 0; i < n; i++)
            {
                if (!vis[i] && dist[u][i] < key[i])
                {
                    parent[i] = u;
                    key[i] = dist[u][i];
                    heap.Add(new Heapi(i, key[i]));
                }
            }
        }
    }
}

