    public static class Prim<T>
    {
        public static UndirectedGraph<T> Mst(UndirectedGraph<T> graph)
        {
            FibonacciHeap<T> pq = new FibonacciHeap<T>();
            Dictionary<T, FibonacciHeap<T>.Entry> entries = new Dictionary<T, FibonacciHeap<T>.Entry>();
            UndirectedGraph<T> result = new UndirectedGraph<T>();
            if (graph.IsEmpty())
                return result;
            IEnumerator<T> it = graph.GetEnumerator();
            it.MoveNext();
            T startNode = it.Current;
            result.AddNode(startNode);
            AddOutgoingEdges(startNode, graph, pq, result, entries);
            for (int i = 0; i < graph.Size() - 1; ++i)
            {
                T toAdd = pq.DequeueMin().GetValue();
                T endpoint = MinCostEndpoint(toAdd, graph, result);
                result.AddNode(toAdd);
                result.AddEdge(toAdd, endpoint, graph.EdgeCost(toAdd, endpoint));
                AddOutgoingEdges(toAdd, graph, pq, result, entries);
            }
            return result;
        }
        private static T MinCostEndpoint(T node, UndirectedGraph<T> graph, UndirectedGraph<T> result)
        {
            T endpoint = default(T);
            double leastCost = double.PositiveInfinity;
            foreach (KeyValuePair<T, double> entry in graph.EdgesFrom(node))
            {
                if (!result.ContainsNode(entry.Key))
                    continue;
                if (entry.Value >= leastCost)
                    continue;
                endpoint = entry.Key;
                leastCost = entry.Value;
            }
            return endpoint;
        }
        private static void AddOutgoingEdges(T node, UndirectedGraph<T> graph, FibonacciHeap<T> pq, UndirectedGraph<T> result, Dictionary<T, FibonacciHeap<T>.Entry> entries)
        {
            foreach (KeyValuePair<T, double> arc in graph.EdgesFrom(node))
            {
                if (result.ContainsNode(arc.Key))
                    continue;
                if (!entries.ContainsKey(arc.Key))
                {
                    entries[arc.Key] = pq.Enqueue(arc.Key, arc.Value);
                }
                else if (entries[arc.Key].GetPriority() > arc.Value)
                {
                    pq.DecreaseKey(entries[arc.Key], arc.Value);
                }
            }
        }
    }
    public class UndirectedGraph<T> : IEnumerable<T>
    {
        private Dictionary<T, Dictionary<T, double>> mGraph = new Dictionary<T, Dictionary<T, double>>();
        public bool AddNode(T node)
        {
            if (mGraph.ContainsKey(node))
                return false;
            mGraph[node] = new Dictionary<T, double>();
            return true;
        }
        public void AddEdge(T one, T two, double length)
        {
            if (!mGraph.ContainsKey(one) || !mGraph.ContainsKey(two))
                throw new KeyNotFoundException("Both nodes must be in the graph.");
            mGraph[one][two] = length;
            mGraph[two][one] = length;
        }
        public void RemoveEdge(T one, T two)
        {
            if (!mGraph.ContainsKey(one) || !mGraph.ContainsKey(two))
                throw new KeyNotFoundException("Both nodes must be in the graph.");
            mGraph[one].Remove(two);
            mGraph[two].Remove(one);
        }
        public double EdgeCost(T one, T two)
        {
            if (!mGraph.ContainsKey(one) || !mGraph.ContainsKey(two))
                throw new KeyNotFoundException("Both nodes must be in the graph.");
            if (!mGraph[one].ContainsKey(two))
                throw new KeyNotFoundException("Edge does not exist in the graph.");
            return mGraph[one][two];
        }
        public IDictionary<T, double> EdgesFrom(T node)
        {
            Dictionary<T, double> arcs;
            if (!mGraph.TryGetValue(node, out arcs))
                throw new KeyNotFoundException("Source node does not exist.");
            return arcs;
        }
        public bool ContainsNode(T node)
        {
            return mGraph.ContainsKey(node);
        }
        public IEnumerator<T> GetEnumerator()
        {
            return mGraph.Keys.GetEnumerator();
        }
        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        {
            return mGraph.Keys.GetEnumerator();
        }
        public int Size()
        {
            return mGraph.Count;
        }
        public bool IsEmpty()
        {
            return mGraph.Count == 0;
        }
    }
    public class FibonacciHeap<T>
    {
        public class Entry
        {
            private int degree = 0;
            private bool isMarked = false;
            private Entry next;
            private Entry prev;
            private Entry parent;
            private Entry child;
            private T elem;
            private double priority;
            public T GetValue()
            {
                return elem;
            }
            public void SetValue(T value)
            {
                elem = value;
            }
            public double GetPriority()
            {
                return priority;
            }
            public Entry(T elem, double priority)
            {
                next = this;
                prev = this;
                this.elem = elem;
                this.priority = priority;
            }
        }
        private Entry mMin = null;
        private int count = 0;
        public Entry Enqueue(T value, double priority)
        {
            CheckPriority(priority);
            Entry result = new Entry(value, priority);
            mMin = MergeLists(mMin, result);
            ++count;
            return result;
        }
        public Entry Min()
        {
            if (IsEmpty())
                throw new KeyNotFoundException("Heap is empty.");
            return mMin;
        }
        public bool IsEmpty()
        {
            return mMin == null;
        }
        public int Size()
        {
            return count;
        }
        public static FibonacciHeap<T> Merge(FibonacciHeap<T> one, FibonacciHeap<T> two)
        {
            FibonacciHeap<T> result = new FibonacciHeap<T>();
            result.mMin = MergeLists(one.mMin, two.mMin);
            result.count = one.count + two.count;
            one.count = two.count = 0;
            one.mMin = null;
            two.mMin = null;
            return result;
        }
        public Entry DequeueMin()
        {
            if (IsEmpty())
                throw new KeyNotFoundException("Heap is empty.");
            --count;
            Entry minElem = mMin;
            if (mMin.next == mMin)
            {
                mMin = null;
            }
            else
            {
                mMin.prev.next = mMin.next;
                mMin.next.prev = mMin.prev;
                mMin = mMin.next;
            }
            if (minElem.child != null)
            {
                Entry curr = minElem.child;
                do
                {
                    curr.parent = null;
                    curr = curr.next;
                } while (curr != minElem.child);
            }
            mMin = MergeLists(mMin, minElem.child);
            if (mMin == null)
                return minElem;
            List<Entry> treeTable = new List<Entry>();
            List<Entry> toVisit = new List<Entry>();
            for (Entry curr = mMin; toVisit.Count == 0 || toVisit[0] != curr; curr = curr.next)
                toVisit.Add(curr);
            foreach (Entry entryItem in toVisit)
            {
                Entry curr = entryItem;
                while (true)
                {
                    while (curr.degree >= treeTable.Count)
                        treeTable.Add(null);
                    if (treeTable[curr.degree] == null)
                    {
                        treeTable[curr.degree] = curr;
                        break;
                    }
                    Entry other = treeTable[curr.degree];
                    treeTable[curr.degree] = null;
                    Entry min = (other.priority < curr.priority) ? other : curr;
                    Entry max = (other.priority < curr.priority) ? curr : other;
                    max.next.prev = max.prev;
                    max.prev.next = max.next;
                    max.next = max.prev = max;
                    min.child = MergeLists(min.child, max);
                    max.parent = min;
                    max.isMarked = false;
                    ++min.degree;
                    curr = min;
                }
                if (curr.priority <= mMin.priority)
                    mMin = curr;
            }
            return minElem;
        }
        public void DecreaseKey(Entry entry, double newPriority)
        {
            CheckPriority(newPriority);
            if (newPriority > entry.priority)
                throw new ArgumentException("New priority exceeds old.");
            DecreaseKeyUnchecked(entry, newPriority);
        }
        public void Delete(Entry entry)
        {
            DecreaseKeyUnchecked(entry, double.NegativeInfinity);
            DequeueMin();
        }
        private void CheckPriority(double priority)
        {
            if (double.IsNaN(priority))
                throw new ArgumentException(priority + " is invalid.");
        }
        private static Entry MergeLists(Entry one, Entry two)
        {
            if (one == null && two == null)
            {
                return null;
            }
            else if (one != null && two == null)
            {
                return one;
            }
            else if (one == null && two != null)
            {
                return two;
            }
            else
            {
                Entry oneNext = one.next;
                one.next = two.next;
                one.next.prev = one;
                two.next = oneNext;
                two.next.prev = two;
                return one.priority < two.priority ? one : two;
            }
        }
        private void DecreaseKeyUnchecked(Entry entry, double priority)
        {
            entry.priority = priority;
            if (entry.parent != null && entry.priority <= entry.parent.priority)
                CutNode(entry);
            if (entry.priority <= mMin.priority)
                mMin = entry;
        }
        private void CutNode(Entry entry)
        {
            entry.isMarked = false;
            if (entry.parent == null)
                return;
            if (entry.next != entry)
            {
                entry.next.prev = entry.prev;
                entry.prev.next = entry.next;
            }
            if (entry.parent.child == entry)
            {
                if (entry.next != entry)
                {
                    entry.parent.child = entry.next;
                }
                else
                {
                    entry.parent.child = null;
                }
            }
            --entry.parent.degree;
            entry.prev = entry.next = entry;
            mMin = MergeLists(mMin, entry);
            if (entry.parent.isMarked)
                CutNode(entry.parent);
            else
                entry.parent.isMarked = true;
            entry.parent = null;
        }
    }
}

