    public Node(E v, Node<E> n)
    {
        Val = v;
        Next = n;
    }
}

class Queue<E>
{
    private int size;
    private Node<E> first;
    private Node<E> last;

    public Queue()
    {
        size = 0;
        first = null;
        last = null;
    }

    public bool IsEmpty()
    {
        return (size == 0);
    }

    public int Size()
    {
        return size;
    }

    public E Dequeue()
    {
        if (IsEmpty())
            return default(E);
        E res = first.Val;
        first = first.Next;
        size--;
        if (first == null)
            last = null;
        return res;
    }

    public void Enqueue(E v)
    {
        Node<E> novo = new Node<E>(v, null);
        if (IsEmpty())
        {
            first = novo;
            last = novo;
        }
        else
        {
            last.Next = null;
            last.Next = novo;
            last = novo;
        }
        size++;
    }
}

class Nos
{
    public int[][] O;
    public int P;
    public int Cnt;
    public int Time;

    public Nos(int[][] ola, int xl)
    {
        O = ola;
        P = xl;
        Cnt = 0;
        Time = 0;
    }

    public void Scc()
    {
        int[][] mt = new int[P][];
        for (int i = 0; i < P; i++)
        {
            mt[i] = new int[P];
        }
        int[] fs = Dfs(O, P);
        mt = Gl(O, P);
        Dfsl(mt, P, fs);
    }

    public void DfsVisitl(int[][] o, string[] color, int[] pais, int h, int p)
    {
        Cnt++;
        color[h] = "gray";
        for (int a = 0; a < p; a++)
        {
            if (o[h][a] == 1)
            {
                if (color[a] == "white")
                {
                    pais[a] = h;
                    DfsVisitl(o, color, pais, a, p);
                }
            }
        }
        color[h] = "black";
    }

    public void Dfsl(int[][] oo, int p, int[] f)
    {
        string[] color = new string[p];
        int[] pais = new int[p];
        for (int i = 0; i < p; i++)
        {
            color[i] = "white";
        }
        for (int i = 0; i < p; i++)
        {
            pais[i] = 0;
        }
        Queue<int> filas = new Queue<int>();
        int u = -1;
        int z = 1;
        int uz = 1;
        while (uz != 0)
        {
            z = Max(p, f);
            if (u != z)
            {
                filas.Enqueue(z);
                f[z] = 0;
                u = z;
            }
            else
            {
                uz = 0;
            }
        }
        int cntg = 0;
        int cntf = 0;
        while (!filas.IsEmpty())
        {
            int q = filas.Dequeue();
            if (color[q] == "white")
            {
                DfsVisitl(oo, color, pais, q, p);
                if (Cnt > 3)
                {
                    cntg++;
                }
                else
                {
                    cntf += Cnt;
                }
                Cnt = 0;
            }
        }
        Console.WriteLine(cntg + " " + cntf);
    }

    public int Max(int p, int[] f)
    {
        int max = 0;
        int ind = 0;
        for (int b = 0; b < p; b++)
        {
            if (max < f[b])
            {
                max = f[b];
                ind = b;
            }
        }
        return ind;
    }

    public int[] Dfs(int[][] o, int p)
    {
        string[] color = new string[p];
        int[] pais = new int[p];
        int[] d = new int[p];
        int[] f = new int[p];
        for (int i = 0; i < p; i++)
        {
            color[i] = "white";
        }
        for (int i = 0; i < p; i++)
        {
            pais[i] = 0;
            f[i] = 0;
            d[i] = 0;
        }
        for (int h = 0; h < p; h++)
        {
            if (color[h] == "white")
            {
                DfsVisit(o, color, pais, h, d, p, f);
            }
        }
        return f;
    }

    public void DfsVisit(int[][] o, string[] color, int[] pais, int h, int[] d, int p, int[] f)
    {
        Time++;
        d[h] = Time;
        color[h] = "gray";
        for (int a = 0; a < p; a++)
        {
            if (o[h][a] == 1)
            {
                if (color[a] == "white")
                {
                    pais[a] = h;
                    DfsVisit(o, color, pais, a, d, p, f);
                }
            }
        }
        color[h] = "black";
        Time++;
        f[h] = Time;
    }

    public int[][] Gl(int[][] matriz, int r)
    {
        int[][] matrizl = new int[r][];
        for (int ii = 0; ii < r; ii++)
        {
            matrizl[ii] = new int[r];
        }
        for (int ii = 0; ii < r; ii++)
        {
            for (int jj = 0; jj < r; jj++)
            {
                if (matriz[ii][jj] == 1)
                {
                    matrizl[jj][ii] = 1;
                }
            }
        }
        return matrizl;
    }
}

