public class Sociologia
{
    static Svertice[] allAlunos;
    static int time;
    static Stack<Svertice> ordemAlunos = new Stack<Svertice>();
    static int[] ocorrencias;
    static int ngrupos;
    static int npessoas;

    public static void Main(string[] args)
    {
        Scanner inn = new Scanner();
        int cases = inn.NextInt();
        for (int cs = 0; cs < cases; cs++)
        {
            int nalunos = inn.NextInt();
            allAlunos = new Svertice[nalunos];
            ocorrencias = new int[nalunos];
            for (int na = 0; na < nalunos; na++)
            {
                int aluno = inn.NextInt();
                int nf = inn.NextInt();
                allAlunos[aluno - 1] = new Svertice(aluno, nf);
                for (int i = 0; i < nf; i++)
                {
                    int temp = inn.NextInt();
                    allAlunos[aluno - 1].AddFriend(temp);
                    ocorrencias[temp - 1]++;
                }
            }
            Dfs();
            CalcularGrafoTransposto();
            DfsT();
            Console.WriteLine("Caso #" + (cs + 1));
            Console.WriteLine(ngrupos + " " + npessoas);
        }
    }

    static void Dfs()
    {
        time = 0;
        ordemAlunos = new Stack<Svertice>();
        foreach (Svertice aluno in allAlunos)
        {
            if (aluno.Color == "white")
            {
                DfsVisit(aluno);
            }
        }
    }

    static void DfsVisit(Svertice aluno)
    {
        time++;
        aluno.StartTime = time;
        aluno.Color = "gray";
        foreach (int idAmigo in aluno.Friends)
        {
            Svertice amigo = allAlunos[idAmigo - 1];
            if (amigo.Color == "white")
            {
                amigo.Parent = aluno;
                DfsVisit(amigo);
            }
        }
        time++;
        aluno.EndTime = time;
        aluno.Color = "black";
        ordemAlunos.Push(aluno);
    }

    static void CalcularGrafoTransposto()
    {
        foreach (Svertice aluno in allAlunos)
        {
            aluno.InitiateFriendsT(ocorrencias[aluno.Id - 1]);
        }
        foreach (Svertice aluno in allAlunos)
        {
            foreach (int amigoId in aluno.Friends)
            {
                allAlunos[amigoId - 1].AddFriendT(aluno.Id);
            }
            aluno.Reset();
        }
    }

    static void DfsT()
    {
        ngrupos = 0;
        npessoas = 0;
        while (ordemAlunos.Count != 0)
        {
            time = 0;
            Svertice aluno = ordemAlunos.Pop();
            if (aluno.Color == "white")
            {
                DfsTVisit(aluno);
                if ((time / 2) >= 4)
                {
                    ngrupos++;
                }
                else
                {
                    npessoas += time / 2;
                }
            }
        }
    }

    static void DfsTVisit(Svertice aluno)
    {
        time++;
        aluno.StartTime = time;
        aluno.Color = "gray";
        foreach (int amigoId in aluno.FriendsT)
        {
            Svertice amigo = allAlunos[amigoId - 1];
            if (amigo.Color == "white")
            {
                amigo.Parent = aluno;
                DfsTVisit(amigo);
            }
        }
        aluno.Color = "black";
        time++;
        aluno.EndTime = time;
    }
}

