class UnionFind
{
    int[] a;

    public UnionFind(int n)
    {
        a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = i;
    }

    public int FindSet(int i)
    {
        if (a[i] == i)
            return i;
        a[i] = FindSet(a[i]);
        return a[i];
    }

    public void UnionSet(int l, int r)
    {
        a[FindSet(l)] = FindSet(r);
    }
}

