class Prob21
{
    static int n;

    static void Main(string[] args)
    {
        Scanner scanner = new Scanner();
        n = scanner.NextInt();
        var nos = new List<No>();
        var arestas = new List<Edge>();
        double comp = 0.0;
        for (int i = 0; i < n; i++)
            nos.Add(new No(scanner.NextDouble(), scanner.NextDouble(), i));
        UnionFind sets = new UnionFind(n);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                arestas.Add(new Edge(nos[i], nos[j]));
        arestas.Sort();
        foreach (Edge e in arestas)
            if (sets.FindSet(e.A.Idx) != sets.FindSet(e.B.Idx))
            {
                sets.UnionSet(e.A.Idx, e.B.Idx);
                comp += Math.Sqrt((e.A.X - e.B.X) * (e.A.X - e.B.X) + (e.A.Y - e.B.Y) * (e.A.Y - e.B.Y));
            }
        Console.Out.WriteLine(string.Format(System.Globalization.CultureInfo.InvariantCulture, "{0:F2}", comp));
    }
}

