public class MainClass
{
    public static void ResetCheckedMatrix(bool[] checkedMatrix, int matrixDim)
    {
        for (int c = 0; c < matrixDim; c++)
            checkedMatrix[c] = false;
    }

    public static void ResetRelationCountMatrix(int[] rcMatrix, int matrixDim)
    {
        for (int c = 0; c < matrixDim; c++)
            rcMatrix[c] = 0;
    }

    public static void FillRelationCountMatrix(bool[][] matrix, int[] rcMatrix, int matrixDim)
    {
        for (int c = 0; c < matrixDim; c++)
            for (int l = 0; l < matrixDim; l++)
            {
                if (matrix[c][l])
                    rcMatrix[c]++;
            }
    }

    public static void ShowRelationCountMatrix(int[] rcMatrix, int matrixDim)
    {
        for (int c = 0; c < matrixDim; c++)
            Console.Write("[" + rcMatrix[c] + "]");
        Console.WriteLine();
    }

    public static void LinkMatrix(bool[][] matrix, int matrixDim)
    {
        for (int c = 0; c < matrixDim; c++)
        {
            for (int l = 0; l < matrixDim; l++)
            {
                if (matrix[c][l])
                {
                    for (int colSearch = 0; colSearch < matrixDim; colSearch++)
                    {
                        if (matrix[l][colSearch])
                            matrix[c][colSearch] = true;
                        if (matrix[colSearch][c])
                            matrix[colSearch][l] = true;
                    }
                }
            }
        }
    }

    public static void ResetMatrix(bool[][] matrix, int matrixDim)
    {
        int c, l;
        for (c = 0; c < matrixDim; c++)
        {
            for (l = 0; l < c; l++)
                matrix[c][l] = false;
            matrix[c][l] = true;
            for (++l; l < matrixDim; l++)
                matrix[c][l] = false;
        }
    }

    public static void ShowMatrix(bool[][] matrix, int matrixDim)
    {
        int c, l;
        Console.Write("|||");
        for (c = 0; c < matrixDim; c++)
            Console.Write("|" + (c + 1) + "|");
        Console.Write("\n");
        for (c = 0; c < matrixDim; c++)
        {
            Console.Write("|" + (c + 1) + "|");
            for (l = 0; l < matrixDim; l++)
            {
                Console.Write("[" + (matrix[c][l] ? 1 : 0) + "]");
            }
            Console.Write("\n");
        }
        Console.WriteLine("\n");
    }

    public static void Main(string[] args)
    {
        InputScanner scanner = new InputScanner();
        int nSituations = scanner.NextInt();
        for (int s = 1; s <= nSituations; s++)
        {
            int matrixDim = scanner.NextInt();
            bool[][] matrix = new bool[matrixDim][];
            for (int r = 0; r < matrixDim; r++)
                matrix[r] = new bool[matrixDim];
            ResetMatrix(matrix, matrixDim);
            for (int i = 0; i < matrixDim; i++)
            {
                int index = scanner.NextInt();
                int relations = scanner.NextInt();
                for (int j = 1; j <= relations; j++)
                {
                    int c = scanner.NextInt();
                    matrix[index - 1][c - 1] = true;
                }
            }
            LinkMatrix(matrix, matrixDim);
            int[] rcMatrix = new int[matrixDim];
            bool[] checkedMatrix = new bool[matrixDim];
            ResetRelationCountMatrix(rcMatrix, matrixDim);
            ResetCheckedMatrix(checkedMatrix, matrixDim);
            FillRelationCountMatrix(matrix, rcMatrix, matrixDim);
            int nGroups = 0;
            int nOut = 0;
            for (int c = 0; c < matrixDim; c++)
            {
                if (checkedMatrix[c])
                    continue;
                int nRelationsC = rcMatrix[c];
                int nElements = 1;
                for (int c1 = 0; c1 < matrixDim; c1++)
                {
                    if (!checkedMatrix[c1] && (c != c1))
                    {
                        int nRelationsC1 = rcMatrix[c1];
                        if (nRelationsC == nRelationsC1)
                        {
                            bool equal = true;
                            for (int l = 0; l < matrixDim; l++)
                            {
                                equal &= (matrix[c][l] == matrix[c1][l]);
                                if (!equal)
                                    break;
                            }
                            if (equal)
                            {
                                checkedMatrix[c] = true;
                                checkedMatrix[c1] = true;
                                nElements++;
                            }
                        }
                    }
                }
                if (nElements < 4)
                    nOut += nElements;
                else
                    nGroups++;
            }
            Console.WriteLine("Caso #" + s + "\n" + nGroups + " " + nOut);
        }
    }
}

