public class Sarda
{
    static void Main()
    {
        var posicoes = new LinkedList<int>();
        var stdin = new Scanner();
        int n = stdin.NextInt();
        No[] g = new No[n];
        for (int i = 0; i < n; i++)
        {
            g[i] = new No(stdin.NextDouble(), stdin.NextDouble(), n);
        }
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                g[i].Dist[j] = Math.Sqrt(Math.Pow(Math.Abs(g[i].X - g[j].X), 2) + Math.Pow(Math.Abs(g[i].Y - g[j].Y), 2));
            }
        }
        double min = 100000.0;
