class Grafo
{
    public No[] G;
    public No[] Gt;
    public int Grupos;
    public int Pessoas;
    public int Ptemp;

    public LinkedList<int> Tempos;

    public Grafo(Scanner input)
    {
        Grupos = 0;
        Tempos = new LinkedList<int>();
        Pessoas = input.NextInt();
        G = new No[Pessoas + 1];
        Gt = new No[Pessoas + 1];
        for (int i = 1; i <= Pessoas; i++)
        {
            G[i] = new No(i);
            Gt[i] = new No(i);
        }
        for (int i = 0; i < Pessoas; i++)
        {
            int ptemp = input.NextInt();
            int am = input.NextInt();
            for (int j = 1; j <= am; j++)
            {
                int amactual = input.NextInt();
                G[ptemp].AddNo(amactual);
                Gt[amactual].AddNo(ptemp);
            }
        }
    }

    public void Dfs()
    {
        for (int i = 1; i <= Pessoas; i++)
        {
            if (!G[i].Visitado)
            {
                DfsVisit(G[i]);
            }
        }
    }

    public void DfsVisit(No actual)
    {
        actual.Visitado = true;
        foreach (int cada in actual.Adj)
        {
            if (!G[cada].Visitado)
            {
                DfsVisit(G[cada]);
            }
        }
        Tempos.AddFirst(actual.Val);
    }

    public void Contar()
    {
        while (Tempos.Count > 0)
        {
            int agora = Tempos.First.Value;
            Tempos.RemoveFirst();
            if (!Gt[agora].Visitado)
            {
                Gt[agora].Visitado = true;
                int pessoast = Contarf(agora);
                if (pessoast >= 4)
                {
                    Grupos++;
                    Pessoas -= pessoast;
                }
            }
        }
    }

    public int Contarf(int pai)
    {
        int contagem = 1;
        Gt[pai].Visitado = true;
        foreach (int adjac in Gt[pai].Adj)
        {
            if (!Gt[adjac].Visitado)
            {
                contagem = contagem + Contarf(adjac);
            }
        }
        return contagem;
    }
}

