public class Sardas
{
    public class Point
    {
        public double x;
        public double y;
        public double dist;
        public Point father;
        public Dictionary<int, double> weight;
        public Point(double x, double y)
        {
            this.x = x;
            this.y = y;
            dist = double.MaxValue;
            weight = new Dictionary<int, double>();
        }
    }
    static double finalDist = 0.00;
    public static void Main(string[] args)
    {
        int n;
        double a, b;
        Scanner input = new Scanner();
        Dictionary<int, Point> board = new Dictionary<int, Point>();
        n = input.NextInt();
        for (int i = 0; i < n; i++)
        {
            a = input.NextDouble();
            b = input.NextDouble();
            board[i] = new Point(a, b);
            if (i == 0)
                board[0].dist = 0;
        }
        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                Point p1 = board[i];
                Point p2 = board[j];
                double count = DoDist(p1, p2);
                p1.weight[j] = count;
                p2.weight[i] = count;
            }
        }
        Dictionary<int, Point> boardCopy = new Dictionary<int, Point>(board);
        DoPrim(board, n);
        DoMinDist(boardCopy, n);
        Console.WriteLine(finalDist.ToString("F2", CultureInfo.InvariantCulture));
    }
    private static void DoMinDist(Dictionary<int, Point> boardCopy, int n)
    {
        for (int i = 0; i < n; i++)
        {
            finalDist += boardCopy[i].dist;
        }
    }
    private static double DoDist(Point p1, Point p2)
    {
        double difx = Math.Abs(p1.x - p2.x);
        double dify = Math.Abs(p1.y - p2.y);
        double count = Math.Sqrt(Math.Pow(difx, 2) + Math.Pow(dify, 2));
        return count;
    }
    private static void DoPrim(Dictionary<int, Point> board, int n)
    {
        while (board.Count > 0)
        {
            int p = ExtractMin(board, n);
            Point point = board[p];
            board.Remove(p);
            for (int i = 1; i < n; i++)
            {
                if (board.ContainsKey(i))
                {
                    Point aux = board[i];
                    if (point.weight[i] < aux.dist)
                    {
                        aux.dist = point.weight[i];
                        aux.father = point;
                    }
                }
            }
        }
    }
    private static int ExtractMin(Dictionary<int, Point> board, int n)
    {
        double minDist = double.MaxValue;
        int p = 0;
        for (int i = 0; i < n; i++)
        {
            if (board.ContainsKey(i))
            {
                Point aux = board[i];
                if (aux.dist < minDist)
                {
                    minDist = aux.dist;
                    p = i;
                }
            }
        }
        return p;
    }
}

