    public bool Visited;

    public No()
    {
        Adjs = new LinkedList<Arco>();
        Visited = false;
    }
}

class Grafo
{
    public No[] Verts;
    public int Nvs, Narcos, Sol, Fora;
    public LinkedList<int> Stack;

    public Grafo(int n)
    {
        Nvs = n;
        Narcos = 0;
        Sol = 0;
        Fora = n;
        Verts = new No[n + 1];
        for (int i = 0; i <= n; i++)
            Verts[i] = new No();
        Stack = new LinkedList<int>();
    }

    public int NumVertices()
    {
        return Nvs;
    }

    public int NumArcos()
    {
        return Narcos;
    }

    public void CleanVisited()
    {
        for (int i = 1; i <= Nvs; i++)
            Verts[i].Visited = false;
    }

    public void Dfs()
    {
        CleanVisited();
        Stack = new LinkedList<int>();
        for (int i = 1; i <= Nvs; i++)
            if (!Verts[i].Visited)
            {
                Verts[i].Visited = true;
                DfsPushstack(i);
            }
    }

    public void DfsPushstack(int c)
    {
        LinkedList<Arco> li = Verts[c].Adjs;
        while (li.Count != 0)
        {
            int next = li.First.Value.ExtremoFinal();
            li.RemoveFirst();
            if (!Verts[next].Visited)
            {
                Verts[next].Visited = true;
                DfsPushstack(next);
            }
        }
        Stack.AddFirst(c);
    }

    public void DfsPopstack(LinkedList<int> stack_)
    {
        Stack = stack_;
        while (Stack.Count != 0)
        {
            int c = Stack.First.Value;
            Stack.RemoveFirst();
            if (!Verts[c].Visited)
            {
                Verts[c].Visited = true;
                LinkedList<int> temp = new LinkedList<int>();
                temp.AddLast(c);
                temp = DfsScc(c, temp);
                if (temp.Count > 3)
                {
                    Sol++;
                    Fora -= temp.Count;
                }
            }
        }
    }

    public LinkedList<int> DfsScc(int c, LinkedList<int> temp)
    {
        foreach (Arco arco in Verts[c].Adjs)
        {
            int next = arco.ExtremoFinal();
            if (!Verts[next].Visited)
            {
                Verts[next].Visited = true;
                temp.AddLast(next);
                DfsScc(next, temp);
            }
        }
        return temp;
    }

    public LinkedList<Arco> AdjsNo(int i)
    {
        return Verts[i].Adjs;
    }

    public void InsertNewArc(int i, int j, int valorIj)
    {
        Verts[i].Adjs.AddLast(new Arco(j, valorIj));
        Narcos++;
    }

    public Arco FindArc(int i, int j)
    {
        foreach (Arco adj in AdjsNo(i))
            if (adj.ExtremoFinal() == j)
                return adj;
        return null;
    }
}

