class Sol
{
    Scanner kb;
    int N;
    int count;
    bool[] visited;
    LinkedList<int> order = new LinkedList<int>();
    List<LinkedList<int>> adj = new List<LinkedList<int>>();
    List<LinkedList<int>> tadj = new List<LinkedList<int>>();
    Dictionary<int, int> map = new Dictionary<int, int>();

    public Sol(Scanner kb)
    {
        this.kb = kb;
    }

    int FindNode(int u)
    {
        if (map.ContainsKey(u))
            return map[u];
        adj.Add(new LinkedList<int>());
        tadj.Add(new LinkedList<int>());
        int p = map.Count;
        map[u] = p;
        return p;
    }

    public void Read()
    {
        N = kb.NextInt();
        map.Clear();
        adj.Clear();
        tadj.Clear();
        for (int i = 0; i < N; i++)
        {
            int u = FindNode(kb.NextInt());
            int c = kb.NextInt();
            for (int k = 0; k < c; k++)
            {
                int v = FindNode(kb.NextInt());
                adj[u].AddLast(v);
                tadj[v].AddLast(u);
            }
        }
        N = map.Count;
    }

    void Dfs(int u)
    {
        if (visited[u])
            return;
        visited[u] = true;
        foreach (int v in adj[u])
        {
            if (!visited[v])
                Dfs(v);
        }
        order.AddFirst(u);
    }

    void FloodFill(int u)
    {
        count++;
        visited[u] = true;
        foreach (int v in tadj[u])
        {
            if (!visited[v])
                FloodFill(v);
        }
    }

    public void Solve()
    {
        order.Clear();
        visited = new bool[N];
        for (int i = 0; i < N; i++)
            Dfs(i);
        for (int i = 0; i < N; i++)
            visited[i] = false;
        int A = 0, B = 0;
        foreach (int u in order)
        {
            if (!visited[u])
            {
                count = 0;
                FloodFill(u);
                if (count >= 4)
                    A++;
                else
                    B += count;
            }
        }
        Console.WriteLine("{0} {1}", A, B);
    }
}

