public class Sociologia
{
    static Scanner ler = new Scanner();
    static Grafo g;
    static Grafo gInv;
    static Stack<int> pilhaDfs = new Stack<int>();
    static List<int> inversa = new List<int>();
    static int nverts;

    public static void Main(string[] args)
    {
        int ncasos = ler.NextInt();
        for (int i = 0; i < ncasos; i++)
        {
            Console.WriteLine("Caso #" + (i + 1));
            Lergrafo();
            Resolveprob();
            Escreveresp();
            Console.WriteLine();
        }
    }

    public static void Lergrafo()
    {
        int nalunos = ler.NextInt();
        Grafo temp = new Grafo(nalunos);
        for (int i = 0; i < nalunos; i++)
        {
            int aluno = ler.NextInt();
            int amigos = ler.NextInt();
            for (int j = 0; j < amigos; j++)
            {
                int amigo = ler.NextInt();
                temp.Verts[aluno].Adjs.Add(new Arco(amigo));
            }
        }
        g = temp;
    }

    public static void Resolveprob()
    {
        gInv = new Grafo(g.Verts.Length);
        for (int i = 1; i <= g.Nvs; i++)
        {
            if (!pilhaDfs.Contains(g.Verts[i].Id))
                Dfs(g, g.Verts[i]);
        }
        gInv = Inverso();
    }

    public static Grafo Inverso()
    {
        Grafo temp = new Grafo(g.Verts.Length);
        for (int i = 0; i < g.Verts.Length; i++)
        {
            for (int j = 0; j < g.Verts[i].Adjs.Count; j++)
            {
                int temp2 = g.Verts[i].Adjs[j].NoFinal;
                temp.Verts[temp2].Adjs.Add(new Arco(i));
            }
        }
        while (pilhaDfs.Count > 0)
            inversa.Add(pilhaDfs.Pop());
        return temp;
    }

    public static void Escreveresp()
    {
        int ngrupos = 0, npessoas, sozinhas = 0;
        int v;
        while (inversa.Count != 0)
        {
            v = inversa[inversa.Count - 1];
            inversa.RemoveAt(inversa.Count - 1);
            nverts = 1;
            DfsInv(gInv, v);
            npessoas = nverts;
            if (npessoas >= 4)
                ngrupos++;
            else
                sozinhas = sozinhas + npessoas;
        }
        Console.Write(ngrupos + " " + sozinhas);
    }

    public static void Dfs(Grafo grafo, No v)
    {
        v.Cor = 1;
        for (int i = 0; i < v.Adjs.Count; i++)
        {
            if (grafo.Verts[v.Adjs[i].NoFinal].Cor == 0)
            {
                grafo.Verts[v.Adjs[i].NoFinal].Cor = 1;
                Dfs(grafo, grafo.Verts[v.Adjs[i].NoFinal]);
            }
        }
        v.Cor = 2;
        pilhaDfs.Push(v.Id);
    }

    public static void DfsInv(Grafo g2, int v)
    {
        g2.Verts[v].Cor = 1;
        if (Procura(v) != -1)
        {
            inversa.RemoveAt(Procura(v));
        }
        for (int i = 0; i < g2.Verts[v].Adjs.Count; i++)
        {
            if (g2.Verts[g2.Verts[v].Adjs[i].NoFinal].Cor == 0)
            {
                nverts++;
                DfsInv(g2, g2.Verts[g2.Verts[v].Adjs[i].NoFinal].Id);
            }
        }
        g2.Verts[v].Cor = 2;
    }

    public static int Procura(int n)
    {
        for (int i = 0; i < inversa.Count; i++)
        {
            if (inversa[i] == n)
                return i;
        }
        return -1;
    }
}

