class Parte3_2
{
    static List<Node> list = new List<Node>();
    static List<Node> aux = new List<Node>();
    static double dist = 0;

    static void Main(string[] args)
    {
        Scanner input = new Scanner();
        int n = input.NextInt();
        for (int i = 0; i < n; i++)
        {
            Node node = new Node(input.NextDouble(), input.NextDouble());
            list.Add(node);
            aux.Add(node);
        }
        Prim();
        Console.Out.Write(string.Format(System.Globalization.CultureInfo.InvariantCulture, "{0:F2}", dist));
        Console.Out.WriteLine();
    }

    static void Prim()
    {
        bool first = true;
        while (list.Count > 0)
        {
            list.Sort();
            Node node = list[0];
            list.RemoveAt(0);
            aux.Remove(node);
            if (!first)
                dist += node.Dist;
            else
                first = false;
            foreach (Node adjNode in aux)
            {
                double weight = ReturnWeight(node, adjNode);
                if (weight < adjNode.Dist)
                {
                    list.Remove(adjNode);
                    adjNode.Parent = node;
                    adjNode.Dist = weight;
                    list.Add(adjNode);
                }
            }
        }
    }

    static double ReturnWeight(Node node1, Node node2)
    {
        return Math.Sqrt((node1.X - node2.X) * (node1.X - node2.X) + (node1.Y - node2.Y) * (node1.Y - node2.Y));
    }
}

