class No
{
    public int Aluno;
    public bool Visitado;
    public List<int> Amigos;
    public List<int> DfsResultado;

    public No(int alu)
    {
        Aluno = alu;
        Amigos = new List<int>();
        DfsResultado = new List<int>();
        Visitado = false;
    }
}

class Grafo
{
    public List<No> Total;

    public Grafo()
    {
        Total = new List<No>();
    }

    public void ColocaGrafo(int alu)
    {
        Total.Add(new No(alu));
    }

    public void AdicionaLigacao(int amigo, int aluno)
    {
        foreach (No n in Total)
        {
            if (n.Aluno == aluno)
                n.Amigos.Add(amigo);
        }
    }

    public void Dfs(Grafo grafo)
    {
        foreach (No n in Total)
        {
            if (!n.Visitado)
                DfsVisit(n, grafo, n);
            foreach (No k in Total)
                k.Visitado = false;
        }
    }

    public void DfsVisit(No z, Grafo grafo, No n)
    {
        n.Visitado = true;
        foreach (int a in n.Amigos)
            foreach (No f in Total)
            {
                if (a == f.Aluno)
                    if (!f.Visitado)
                        DfsVisit(z, grafo, f);
            }
        z.DfsResultado.Add(n.Aluno);
    }

    public static void Main(string[] args)
    {
        Scanner inn = new Scanner();
        int count = 1;
        int ncenarios = inn.NextInt();
        List<int> fim = new List<int>();
        while (count <= ncenarios)
        {
            int ngrupos = 0, nsgrupo = 0;
            int nalunos = inn.NextInt();
            Grafo grafo = new Grafo();
            Grafo grafoT = new Grafo();
            for (int i = 1; i <= nalunos; i++)
            {
                grafo.ColocaGrafo(i);
                grafoT.ColocaGrafo(i);
            }
            for (int i = 0; i < nalunos; i++)
            {
                int aluno = inn.NextInt();
                int namigos = inn.NextInt();
                for (int j = 0; j < namigos; j++)
                {
                    int amigo = inn.NextInt();
                    grafo.AdicionaLigacao(amigo, aluno);
                    grafoT.AdicionaLigacao(aluno, amigo);
                }
            }
            grafo.Dfs(grafo);
            grafoT.Dfs(grafoT);
            foreach (No n in grafo.Total)
            {
                if (!n.Visitado)
                {
                    fim = n.DfsResultado;
                    foreach (No t in grafoT.Total)
                        if (t.Aluno == n.Aluno)
                        {
                            List<int> mantida = new List<int>();
                            foreach (int x in fim)
                                if (t.DfsResultado.Contains(x))
                                    mantida.Add(x);
                            fim = mantida;
                            n.DfsResultado = mantida;
                        }
                    foreach (int h in fim)
                    {
                        foreach (No f in grafo.Total)
                        {
                            if (h == f.Aluno && f.DfsResultado.Count != 1)
                                f.Visitado = true;
                        }
                    }
                    if (fim.Count >= 4)
                        ngrupos++;
                }
            }
            foreach (No n in grafo.Total)
                if (!n.Visitado)
                    nsgrupo++;
            if (ngrupos == 0)
                nsgrupo = nalunos;
            Console.WriteLine("Caso #" + count);
            Console.WriteLine(ngrupos + " " + nsgrupo);
            count++;
        }
    }
}

