class Aluno
{
    public int cod;
    public int place;
    public int place2;
    public bool estado;

    public Aluno(int c)
    {
        cod = c;
        place = 0;
        place2 = 0;
        estado = false;
    }
}

class Socio
{
    static int Lugar(Aluno[] gr, int val, int t)
    {
        for (int i = 1; i <= t; i++)
            if (gr[i].place == val)
                return i;
        return -1;
    }

    static int Dfs(Aluno[] gr, int k, int pl, bool[][] m, int t)
    {
        gr[k].estado = true;
        for (int i = 1; i <= t; i++)
            if (!gr[i].estado && m[k][i])
                pl = Dfs(gr, i, pl, m, t);
        gr[k].place = pl;
        pl++;
        return pl;
    }

    static int Dfsv(Aluno[] gr, int k, int pl, bool[][] m, int t)
    {
        gr[k].estado = false;
        for (int i = 1; i <= t; i++)
            if (gr[i].estado && m[i][k])
                pl = Dfsv(gr, i, pl, m, t);
        gr[k].place2 = pl;
        pl++;
        return pl;
    }

    public static void Main(string[] args)
    {
        InputScanner kb = new InputScanner();
        int cenar = kb.NextInt();
        for (int i = 1; i <= cenar; i++)
        {
            int grupos = 0;
            int solos = 0;
            int alunos = kb.NextInt();
            Aluno[] lista = new Aluno[alunos + 1];
            bool[][] matr = new bool[alunos + 1][];
            for (int r = 0; r <= alunos; r++)
                matr[r] = new bool[alunos + 1];
            for (int j = 1; j <= alunos; j++)
            {
                int cod = kb.NextInt();
                lista[j] = new Aluno(j);
                int amigos = kb.NextInt();
                for (int z = 0; z < amigos; z++)
                {
                    int am = kb.NextInt();
                    matr[cod][am] = true;
                }
            }
            int lug = 1;
            for (int j = 1; j <= alunos; j++)
            {
                if (!lista[j].estado)
                {
                    lug = Dfs(lista, j, lug, matr, alunos);
                }
            }
            lug = 1;
            int p = 1;
            for (int j = alunos; j > 0; j--)
            {
                int k = Lugar(lista, j, alunos);
                if (lista[k].estado)
                {
                    lug = Dfsv(lista, k, lug, matr, alunos);
                    if ((lug - p) > 3)
                        grupos++;
                    else
                        solos = solos + lug - p;
                    p = lug;
                }
            }
            Console.WriteLine("Caso #" + i);
            Console.WriteLine(grupos + " " + solos);
        }
    }
}

