class Node : IComparable<Node>
{
    public int number;
    public bool visited;
    public float distance;
    public Node parent;
    public int chosen;
    public float chosenValue;
    public float posx;
    public float posy;
    public Node(bool visited, int number, float distance, Node parent, int chosen, float chosenValue, float posx, float posy)
    {
        this.number = number;
        this.visited = visited;
        this.distance = distance;
        this.parent = parent;
        this.chosen = chosen;
        this.chosenValue = chosenValue;
        this.posx = posx;
        this.posy = posy;
    }
    public int CompareTo(Node x)
    {
        if (this.distance < x.distance)
            return -1;
        else if (this.distance > x.distance)
            return 1;
        else
        {
            if (this.number < x.number)
                return -1;
            else if (this.number > x.number)
                return 1;
            else
                return 0;
        }
    }
}

class PriorityQueue<T> where T : IComparable<T>
{
    private List<T> heap = new List<T>();
    public bool IsEmpty()
    {
        return heap.Count == 0;
    }
    public void Add(T item)
    {
        heap.Add(item);
        SiftUp(heap.Count - 1);
    }
    public bool Contains(T item)
    {
        return heap.Contains(item);
    }
    public void Remove(T item)
    {
        int i = heap.IndexOf(item);
        T last = heap[heap.Count - 1];
        heap.RemoveAt(heap.Count - 1);
        if (i < heap.Count)
        {
            heap[i] = last;
            SiftDown(i);
            SiftUp(i);
        }
    }
    public T RemoveHead()
    {
        T head = heap[0];
        T last = heap[heap.Count - 1];
        heap.RemoveAt(heap.Count - 1);
        if (heap.Count > 0)
        {
            heap[0] = last;
            SiftDown(0);
        }
        return head;
    }
    private void SiftUp(int i)
    {
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (heap[i].CompareTo(heap[parent]) < 0)
            {
                T tmp = heap[i];
                heap[i] = heap[parent];
                heap[parent] = tmp;
                i = parent;
            }
            else
            {
                break;
            }
        }
    }
    private void SiftDown(int i)
    {
        int n = heap.Count;
        while (true)
        {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = i;
            if (left < n && heap[left].CompareTo(heap[smallest]) < 0)
                smallest = left;
            if (right < n && heap[right].CompareTo(heap[smallest]) < 0)
                smallest = right;
            if (smallest == i)
                break;
            T tmp = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = tmp;
            i = smallest;
        }
    }
}

