using System;
using System.Collections.Generic;
using System.Globalization;

class Node
{
    public LinkedList<int> Adj;
    public double Distance;
    public double Y;
    public double X;
    public int Pai;
    public Node(double x, double y)
    {
        Adj = new LinkedList<int>();
        Distance = 0.0;
        X = x;
        Y = y;
        Pai = 0;
    }
}

class Graph
{
    public int n;
    public Node[] nodes;
    public Graph(int n)
    {
        this.n = n;
        nodes = new Node[n + 1];
    }
    public double Peso(int x, int y)
    {
        double p = Math.Sqrt(((nodes[x].X - nodes[y].X) * (nodes[x].X - nodes[y].X)) + ((nodes[x].Y - nodes[y].Y) * (nodes[x].Y - nodes[y].Y)));
        return p;
    }
    public void Prim(int v)
    {
        var q = new LinkedList<int>();
        for (int i = 1; i <= n; i++)
        {
            nodes[i].Distance = double.MaxValue;
            q.AddLast(i);
        }
        nodes[v].Distance = 0;
        double min = double.MaxValue;
        int u = 0;
        int menor = 0;
        while (q.Count > 0)
        {
            min = double.MaxValue;
            for (int i = 1; i <= n; i++)
                if (q.Contains(i) && nodes[i].Distance < min)
                {
                    min = nodes[i].Distance;
                    menor = i;
                }
            q.RemoveFirstOccurrence(menor);
            u = menor;
            foreach (int w in nodes[u].Adj)
            {
                double p = Peso(u, w);
                if (q.Contains(w) && p < nodes[w].Distance)
                {
                    nodes[w].Pai = u;
                    nodes[w].Distance = p;
                }
            }
        }
    }
}

