            for (int a = 0; a < nNumAlumni; a++)
            {
                arGroups[a] = new int[nNumAlumni];
                arTransp[a] = new int[nNumAlumni];
            }
            arVisited = new int[nNumAlumni];
            for (int j = 0; j < nNumAlumni; j++)
            {
                nIdAl = myscan.NextInt();
                nNumFriends = myscan.NextInt();
                for (int k = 0; k < nNumFriends; k++)
                {
                    nIdAl2 = myscan.NextInt();
                    arGroups[nIdAl - 1][nIdAl2 - 1] = 1;
                    arTransp[nIdAl2 - 1][nIdAl - 1] = 1;
                }
            }
            for (int l = 0; l < nNumAlumni; l++)
            {
                arVisited[l] = 0;
            }
            alOnAGroup = new List<int>();
            CC(arGroups, arVisited);
            CC_Transp(nNumGroup, arTransp, arVisited, alOnAGroup, i);
        }
    }

    public static void CC(int[][] arGroups, int[] arVisited)
    {
        for (int i = 0; i < arVisited.Length; i++)
        {
            if (arVisited[i] == 0)
            {
                DFS(arGroups, arVisited, i);
            }
        }
    }

    public static void CC_Transp(int nNumGroup, int[][] arGroups, int[] arVisited, List<int> alOnAGroup, int nCase)
    {
        int nDummy = 0;
        for (int i = 0; i < arVisited.Length; i++)
        {
            if (arVisited[i] < 2)
            {
                NCountElem = 0;
                DFS_Transp(arGroups, arVisited, alOnAGroup, i);
                if (NCountElem >= 4)
                {
                    nNumGroup++;
                }
                else
                {
                    for (int j = 1; j <= NCountElem && alOnAGroup.Count > 0; j++)
                    {
                        nDummy = alOnAGroup[alOnAGroup.Count - 1];
                        alOnAGroup.RemoveAt(alOnAGroup.Count - 1);
                    }
                }
            }
        }
        Console.WriteLine("Caso #" + (nCase + 1));
        Console.WriteLine(nNumGroup + " " + (arVisited.Length - alOnAGroup.Count));
    }

    public static void DFS(int[][] arGroups, int[] arVis, int n)
    {
        arVis[n]++;
        for (int i = 0; i < arGroups[n].Length; i++)
        {
            if (arVis[i] == 0 && arGroups[n][i] != 0)
            {
                DFS(arGroups, arVis, i);
            }
        }
    }

    public static void DFS_Transp(int[][] arGroups, int[] arVis, List<int> alOnAGroup, int n)
    {
        arVis[n]++;
        if (arVis[n] > 1)
        {
            alOnAGroup.Add(n);
            NCountElem++;
        }
        for (int i = 0; i < arGroups[n].Length; i++)
        {
            if (arVis[i] < 2 && arGroups[n][i] != 0)
            {
                DFS_Transp(arGroups, arVis, alOnAGroup, i);
            }
        }
    }
}

