    static int distMin;

    static void Bfs()
    {
        var x = new LinkedList<int>();
        var y = new LinkedList<int>();
        for (int i = 0; i < l; i++)
            for (int j = 0; j < c; j++)
                if (matriz[i][j] != '#')
                {
                    x.AddLast(i);
                    y.AddLast(j);
                    nodes[i][j].Visited = true;
                    nodes[i][j].Distance = 0;
                }
        while (x.Count > 0)
        {
            int u = x.First.Value;
            x.RemoveFirst();
            int v = y.First.Value;
            y.RemoveFirst();
            if (v < c - 1)
                if (!nodes[u][v + 1].Visited)
                {
                    x.AddLast(u);
                    y.AddLast(v + 1);
                    nodes[u][v + 1].Visited = true;
                    nodes[u][v + 1].Distance = nodes[u][v].Distance + 1;
                }
            if (v > 0)
                if (!nodes[u][v - 1].Visited)
                {
                    x.AddLast(u);
                    y.AddLast(v - 1);
                    nodes[u][v - 1].Visited = true;
                    nodes[u][v - 1].Distance = nodes[u][v].Distance + 1;
                }
            if (u < l - 1)
                if (!nodes[u + 1][v].Visited)
                {
                    x.AddLast(u + 1);
                    y.AddLast(v);
                    nodes[u + 1][v].Visited = true;
                    nodes[u + 1][v].Distance = nodes[u][v].Distance + 1;
                }
            if (u > 0)
                if (!nodes[u - 1][v].Visited)
                {
                    x.AddLast(u - 1);
                    y.AddLast(v);
                    nodes[u - 1][v].Visited = true;
                    nodes[u - 1][v].Distance = nodes[u][v].Distance + 1;
                }
        }
