        for (int i = 0; i < l; i++)
            for (int j = 0; j < c; j++)
                nodes[i][j] = new Node3();
        Bfs();
        for (int i = 0; i < l; i++)
            for (int j = 0; j < c; j++)
                if (matriz[i][j] == 'A')
