    {
        InputScanner input = new InputScanner();
        int nC = input.NextInt();
        for (int i = 1; i <= nC; i++)
        {
            Run(input, i);
        }
        input.Close();
    }

    static void Dfs1(Aluno aluno, LinkedList<Aluno> f)
    {
        if (!aluno.visitado)
        {
            aluno.visitado = true;
            foreach (int a in aluno.amigos)
                Dfs1(alunos[a], f);
            f.AddLast(aluno);
        }
    }

    static void Dfs2(Aluno aluno)
    {
        if (aluno.visitadoT)
            return;
        c++;
        aluno.visitadoT = true;
        foreach (int a in aluno.amigosT)
            Dfs2(alunos[a]);
    }

    static void Run(InputScanner input, int caso)
    {
        int n = input.NextInt();
        alunos = new Aluno[n + 1];
        for (int i = 1; i <= n; i++)
            alunos[i] = new Aluno(i);
        LinkedList<Aluno> f = new LinkedList<Aluno>();
        for (int i = 1; i <= n; i++)
        {
            int a = input.NextInt();
            int na = input.NextInt();
            for (; na > 0; na--)
            {
                int k = input.NextInt();
                alunos[a].amigos.AddLast(k);
                alunos[k].amigosT.AddLast(a);
            }
        }
        for (int i = 1; i <= n; i++)
            Dfs1(alunos[i], f);
        int x = 0, y = 0;
        foreach (Aluno a in f)
        {
            if (a.visitadoT)
                continue;
            c = 0;
            Dfs2(a);
            if (c >= 4)
                x++;
            else
                y += c;
        }
        Console.WriteLine("Caso #" + caso + "\n" + x + " " + y);
    }
