class Social
{
    public static Stack<int> s = new Stack<int>();
    public static int ctr = 0;
    public static int[] flood;

    public static void PrintGraph(List<List<int>> g)
    {
        for (int i = 1; i < g.Count; i++)
        {
            Console.Write(i + " -> ");
            for (int j = 0; j < g[i].Count; j++)
                Console.Write(g[i][j] + " ");
            Console.WriteLine();
        }
    }

    public static void Dfs(List<List<int>> g)
    {
        int[] v = new int[g.Count];
        for (int i = 1; i < g.Count; i++)
            if (v[i] == 0)
                RunDfs(g, i, v);
    }

    public static void RunDfs(List<List<int>> g, int n, int[] v)
    {
        v[n] = 1;
        for (int i = 0; i < g[n].Count; i++)
            if (v[g[n][i]] == 0)
                RunDfs(g, g[n][i], v);
        if (!s.Contains(n))
            s.Push(n);
    }

    public static List<List<int>> Transpose(List<List<int>> g)
    {
        List<List<int>> st = new List<List<int>>();
        for (int i = 0; i < g.Count; i++)
            st.Add(new List<int>());
        for (int i = 0; i < g.Count; i++)
            for (int j = 0; j < g[i].Count; j++)
                st[g[i][j]].Add(i);
        return st;
    }

    public static void Solve(List<List<int>> g)
    {
        flood = new int[g.Count];
        while (s.Count > 0)
        {
            int n = s.Pop();
            if (flood[n] == 0)
            {
                ctr++;
                Solve2(g, n, flood);
            }
        }
    }

    public static void Solve2(List<List<int>> g, int n, int[] flood)
    {
        flood[n] = ctr;
        for (int i = 0; i < g[n].Count; i++)
            if (flood[g[n][i]] == 0)
                Solve2(g, g[n][i], flood);
    }

    public static void Main(string[] args)
    {
        InputScanner input = new InputScanner();
        int nrcases = input.NextInt();
        for (int k = 0; k < nrcases; k++)
        {
            Console.WriteLine("Caso #" + (k + 1));
            List<List<int>> g = new List<List<int>>();
            s = new Stack<int>();
            ctr = 0;
            int nrnodes = input.NextInt();
            for (int i = 0; i < nrnodes + 1; i++)
                g.Add(new List<int>());
            for (int i = 0; i < nrnodes; i++)
            {
                int node = input.NextInt();
                int nrcons = input.NextInt();
                for (int j = 0; j < nrcons; j++)
                    g[node].Add(input.NextInt());
            }
            Dfs(g);
            g = Transpose(g);
            Solve(g);
            Array.Sort(flood);
            int groups = 0;
            int pplgro = 0;
            for (int i = 1; i < flood.Length; i++)
            {
                int nrppl = 0;
                for (int j = 0; j < flood.Length; j++)
                    if (flood[j] == i)
                        nrppl++;
                if (nrppl >= 4)
                {
                    groups++;
                    pplgro += nrppl;
                }
            }
            Console.WriteLine(groups + " " + (nrnodes - pplgro));
        }
    }
}

