class Edge : IComparable<Edge>
{
    public int U;
    public int V;
    public double Cost;
    public Edge() : this(0, 0, 0)
    {
    }
    public int CompareTo(Edge other)
    {
        if (Cost == other.Cost)
            return 0;
        else
            return Cost < other.Cost ? -1 : 1;
    }
    public override string ToString()
    {
        return "(" + U + "," + V + "," + Cost + ")";
    }
    public Edge(int u, int v, double c)
    {
        U = u;
        V = v;
        Cost = c;
    }
}

class DisjointSet
{
    int[] p;
    int[] rank;
    public DisjointSet(int n)
    {
        p = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++)
        {
            p[i] = i;
            rank[i] = 0;
        }
    }
    public int FindSet(int x)
    {
        if (p[x] != x)
            p[x] = FindSet(p[x]);
        return p[x];
    }
    public void Union(int x, int y)
    {
        Link(FindSet(x), FindSet(y));
    }
    void Link(int x, int y)
    {
        if (rank[x] > rank[y])
            p[y] = x;
        else
        {
            p[x] = y;
            if (rank[x] == rank[y])
                rank[y]++;
        }
    }
}

class Sol
{
    Scanner kb;
    double[][] points;
    public Sol(Scanner kb)
    {
        this.kb = kb;
    }
    double Distance(int i, int k)
    {
        double dx = points[k][0] - points[i][0];
        double dy = points[k][1] - points[i][1];
        return Math.Sqrt(dx * dx + dy * dy);
    }
    public void Solve()
    {
        int n = kb.NextInt();
        points = new double[n][];
        for (int i = 0; i < n; i++)
        {
            points[i] = new double[2];
            points[i][0] = kb.NextDouble();
            points[i][1] = kb.NextDouble();
        }
        var edges = new List<Edge>();
        for (int i = 0; i < n; i++)
        {
            for (int k = i + 1; k < n; k++)
            {
                edges.Add(new Edge(i, k, Distance(i, k)));
            }
        }
        edges.Sort();
        DisjointSet s = new DisjointSet(n);
        int count = 0;
        double total = 0;
        foreach (Edge e in edges)
        {
            if (s.FindSet(e.U) != s.FindSet(e.V))
            {
                s.Union(e.U, e.V);
                total += e.Cost;
                count++;
                if (count == n - 1)
                    break;
            }
        }
        Console.WriteLine(total.ToString("F2", CultureInfo.InvariantCulture));
    }
}

