class Stack
{
    int elems;
    Node first;

    public Stack()
    {
        elems = 0;
        first = null;
    }

    public int ElemsStack()
    {
        return elems;
    }

    public void Push(int x)
    {
        Node no = new Node(x);
        no.SetNext(first);
        first = no;
        elems++;
    }

    public int Pop()
    {
        int x = first.GetValor();
        first = first.GetNext();
        elems--;
        return x;
    }

    public bool IsEmpty()
    {
        return first == null;
    }

    public bool ElemInStack(int x)
    {
        for (Node i = first; i != null; i = i.GetNext())
            if (i.GetValor() == x)
                return true;
        return false;
    }

    public Stack GetTill(int v)
    {
        Stack s = new Stack();
        do
        {
            int i = Pop();
            s.Push(i);
        } while (PeekLast() != v);
        return s;
    }

    int PeekLast()
    {
        return first.GetValor();
    }
}

