{
    static Scanner sca = new Scanner();

    public static void Main(string[] args)
    {
        Input();
    }

    static void Input()
    {
        Resultados resus = new Resultados();
        int nCenarios = sca.NextInt();
        for (int cenario = 1; cenario <= nCenarios; cenario++)
        {
            int nAlunos = sca.NextInt();
            Vertice[] alunos = new Vertice[nAlunos];
            for (int aluno = 0; aluno < nAlunos; aluno++)
            {
                int id = sca.NextInt();
                int nAmigos = sca.NextInt();
                int[] amigos = new int[nAmigos];
                for (int i = 0; i < nAmigos; i++)
                {
                    amigos[i] = sca.NextInt() - 1;
                }
                alunos[id - 1] = new Vertice(nAmigos, amigos);
            }
            resus.AdicionarResultado(ContagemDeGrupos(cenario, nAlunos, alunos));
        }
        Output(resus);
    }

    static Resultado ContagemDeGrupos(int cenario, int nAlunos, Vertice[] alunos)
    {
        bool[] analisados = new bool[nAlunos];
        Stack pilha = new Stack();
        List<Stack> listaComp = new List<Stack>();
        int nGrupos4 = 0;
        int outros = 0;
        int index = 0;
        while (true)
        {
            int i = PrimeiroNaoAnalisado(analisados, nAlunos);
            if (i == -1)
                break;
            listaComp = Tarjan(alunos, i, index, pilha, listaComp);
            foreach (Stack p2 in listaComp)
            {
                int elementosNaPilha = p2.ElemsStack();
                if (elementosNaPilha >= 4)
                    nGrupos4++;
                else
                    outros += elementosNaPilha;
                while (!p2.IsEmpty())
                {
                    analisados[p2.Pop()] = true;
                }
            }
            listaComp = new List<Stack>();
        }
        return new Resultado(cenario, nGrupos4, outros);
    }

    static int PrimeiroNaoAnalisado(bool[] estado, int n)
    {
        for (int i = 0; i < n; i++)
            if (!estado[i])
                return i;
        return -1;
    }

    static List<Stack> Tarjan(Vertice[] alunos, int v, int index, Stack pilha, List<Stack> listaComp)
    {
        int indexLocal = IndexHolder.index;
        IndexHolder.index++;
        pilha.Push(v);
        int nAmigos = alunos[v].GetNAmigos();
        for (int i = 0; i < nAmigos; i++)
        {
            int amigo = alunos[v].Amigo(i);
            if (IndexHolder.state[amigo].index == -1)
            {
                Tarjan(alunos, amigo, indexLocal, pilha, listaComp);
                IndexHolder.state[v].lowlink = Math.Min(IndexHolder.state[v].lowlink, IndexHolder.state[amigo].lowlink);
            }
            else if (pilha.ElemInStack(amigo))
            {
                IndexHolder.state[v].lowlink = Math.Min(IndexHolder.state[v].lowlink, IndexHolder.state[amigo].index);
            }
        }
        if (IndexHolder.state[v].lowlink == IndexHolder.state[v].index)
        {
            listaComp.Add(pilha.GetTill(v));
        }
        return listaComp;
    }

    static void Output(Resultados resus)
    {
        for (Resultado i = resus.primeiro; i != null; i = i.Proximo())
        {
            Console.WriteLine("Caso #" + i.caso + "\n" + i.gruposDe4 + " " + i.outrosElementos);
        }
    }
}

