        }
        for (int i = 1; i <= nos; i++) {
            for (int j = 1; j <= nos; j++) {
                if (i != j) {
                    g.nodes[i].adj.add(new Aresta(j, g.distance(g.nodes[i], g.nodes[j])));
                }
            }
        }
        g.Prim(1);
    }
}

