import java.util.ArrayList;
import java.util.PriorityQueue;
import java.util.Scanner;
class Point {
    double x, y;
    Point(double x, double y) {
        this.x = x;
        this.y = y;
    }
}
class Edge implements Comparable<Edge> {
    double x1, y1, x2, y2;
    int node1, node2;
    Edge(int node1, int node2, double x1, double y1, double x2, double y2) {
        this.node1 = node1;
        this.node2 = node2;
        this.x1 = x1;
        this.y1 = y1;
        this.x2 = x2;
        this.y2 = y2;
    }
    public double getDistance() {
        return Math.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
    }
    public int compareTo(Edge e) {
        if (getDistance() < e.getDistance())
            return -1;
        return 1;
    }
}
public class Prob21 {
    public static void main(String[] args) {
        Scanner stdin = new Scanner(System.in);
        int n = stdin.nextInt();
        Point[] p = new Point[n];
        String s = stdin.nextLine();
        for (int i = 0; i < n; i++) {
            String[] line = stdin.nextLine().split(" ");
            double a = Double.parseDouble(line[0]);
            double b = Double.parseDouble(line[1]);
            p[i] = new Point(a, b);
        }
        PriorityQueue<Edge> pq = new PriorityQueue<Edge>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                Edge edge = new Edge(i, j, p[i].x, p[i].y, p[j].x, p[j].y);
                pq.add(edge);
            }
        }
        boolean[] added = new boolean[n];
        double total = 0;
        Edge temp = pq.remove();
        added[temp.node1] = true;
        added[temp.node2] = true;
        total += temp.getDistance();
        boolean found = false;
        ArrayList<Edge> tempList = new ArrayList<Edge>();
        while (!pq.isEmpty() && !found) {
            Edge temp2 = pq.remove();
            if ((added[temp2.node1] && !added[temp2.node2]) || (!added[temp2.node1] && added[temp2.node2])) {
                added[temp2.node1] = true;
                added[temp2.node2] = true;
                total += temp2.getDistance();
                pq.addAll(tempList);
                tempList.clear();
            } else if (!added[temp2.node1] && !added[temp2.node2])
                tempList.add(temp2);
        }
        System.out.printf("%.2f\n", total);
    }
}

import java.util.*;
public class prob21 {
    static int[] pset;
    static class ramo implements Comparable<ramo> {
        int u;
        int v;
        double w;
        public ramo(int st, int end, double we) {
            u = st;
            v = end;
            w = we;
        }
        @Override public int compareTo(ramo o) {
            if (w > o.w)
                return -1;
            else
                return 1;
        }
    }
    static int findSet(int i) {
        if (pset[i] == i) {
            return i;
        } else {
            return pset[i] = findSet(pset[i]);
        }
    }
    static void unionSet(int i, int j) {
        pset[findSet(i)] = pset[findSet(j)];
    }
    static boolean isSameSet(int i, int j) {
        return findSet(i) == findSet(j);
    }
    public static void initSet(int tamanho) {
        pset = new int[tamanho];
        for (int i = 0; i < tamanho; i++) {
            pset[i] = i;
        }
    }
    public static void main(String[] args) throws Exception {
        Scanner ler = new Scanner(System.in);
        PriorityQueue<ramo> ramoList = new PriorityQueue<ramo>();
        int n = ler.nextInt();
        double[][] cord = new double[n][2];;
        double currLen;
        double yDiff, xDiff;
        double min = 0.0;
        for (int i = 0; i < n; i++) {
            min = 0;
            initSet(n);
            cord[i][0] = ler.nextDouble();
            cord[i][1] = ler.nextDouble();
            for (int j = 0; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    xDiff = cord[j][0] - cord[k][0];
                    yDiff = cord[j][1] - cord[k][1];
                    currLen = Math.sqrt(yDiff * yDiff + xDiff * xDiff);
                    ramo e = new ramo(j, k, -currLen);
                    ramoList.add(e);
                }
            }
            while (!ramoList.isEmpty()) {
                ramo e = ramoList.poll();
                if (!isSameSet(e.u, e.v)) {
                    min += -e.w;
                    unionSet(e.u, e.v);
                }
            }
        }
        System.out.printf("%.2f\n", min);
    }
}

import java.util.*;
class Aluno {
    int cod;
    int place;
    int place2;
    boolean estado;
    Aluno(int c) {
        cod = c;
        place = 0;
        place2 = 0;
        estado = false;
    }
}
class socio {
    static int lugar(Aluno[] gr, int val, int t) {
        for (int i = 1; i <= t; i++)
            if (gr[i].place == val)
                return i;
        return -1;
    }
    static int dfs(Aluno[] gr, int k, int pl, boolean[][] m, int t) {
        gr[k].estado = true;
        for (int i = 1; i <= t; i++)
            if (!gr[i].estado && m[k][i])
                pl = dfs(gr, i, pl, m, t);
        gr[k].place = pl;
        pl++;
        return pl;
    }
    static int dfsv(Aluno[] gr, int k, int pl, boolean[][] m, int t) {
        gr[k].estado = false;
        for (int i = 1; i <= t; i++)
            if (gr[i].estado && m[i][k])
                pl = dfsv(gr, i, pl, m, t);
        gr[k].place2 = pl;
        pl++;
        return pl;
    }
    public static void main(String[] args) {
        Scanner kb = new Scanner(System.in);
        int cenar = kb.nextInt();
        for (int i = 1; i <= cenar; i++) {
            int grupos = 0;
            int solos = 0;
            int alunos = kb.nextInt();
            Aluno[] lista = new Aluno[alunos + 1];
            boolean[][] matr = new boolean[alunos + 1][alunos + 1];
            for (int j = 1; j <= alunos; j++) {
                int cod = kb.nextInt();
                lista[j] = new Aluno(j);
                int amigos = kb.nextInt();
                for (int z = 0; z < amigos; z++) {
                    int am = kb.nextInt();
                    matr[cod][am] = true;
                }
            }
            int lug = 1;
            for (int j = 1; j <= alunos; j++) {
                if (!lista[j].estado) {
                    lug = dfs(lista, j, lug, matr, alunos);
                }
            }
            lug = 1;
            int p = 1;
            for (int j = alunos; j > 0; j--) {
                int k = lugar(lista, j, alunos);
                if (lista[k].estado) {
                    lug = dfsv(lista, k, lug, matr, alunos);
                    if ((lug - p) > 3)
                        grupos++;
                    else
                        solos = solos + lug - p;
                    p = lug;
                }
            }
            System.out.println("Caso #" + i);
            System.out.println(grupos + " " + solos);
        }
    }
}

