    static void makeSet(int n1) {
        pset = new int[n1];
        rank = new int[n1];
        for (int i = 0; i < n1; i++) {
            pset[i] = i;
            rank[i] = 0;
        }
    }
    static int findSet(int i) {
        if (i != pset[i]) {
            pset[i] = findSet(pset[i]);
        }
        return pset[i];
    }
    static boolean isSameSet(int i, int j) {
        return findSet(i) == findSet(j);
    }
    static void Union(int i, int j) {
        int xRz = findSet(i);
        int yRz = findSet(j);
        if (rank[xRz] > rank[yRz])
            pset[yRz] = xRz;
        else {
            pset[xRz] = yRz;
            if (rank[xRz] == rank[yRz])
                ++rank[yRz];
        }
    }
    static double kruskall() {
        double cost = 0;
        makeSet(n);
        Collections.sort(nodelist);
        for (int i = 0; i < nodelist.size(); ++i) {
            Node node = nodelist.get(i);
            if (!isSameSet(node.from, node.to)) {
                Union(node.from, node.to);
                cost += node.w;
            }
        }
        return cost;
    }
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        double[] xcord = new double[n];
        double[] ycord = new double[n];
        nodelist = new ArrayList<Node>();
        for (int i = 0; i < n; ++i) {
            xcord[i] = in.nextDouble();
            ycord[i] = in.nextDouble();
        }
        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                double dx = xcord[i] - xcord[j];
                double dy = ycord[i] - ycord[j];
                double d = Math.sqrt(dx * dx + dy * dy);
                nodelist.add(new Node(d, i, j));
                nodelist.add(new Node(d, j, i));
            }
        }
        System.out.println(String.format("%.2f", kruskall()));
    }
}

import java.util.*;
class sol {
    Scanner kb;
    sol(Scanner kb) {
        this.kb = kb;
    }
    int N;
    int count;
    boolean[] visited;
    Deque<Integer> order = new LinkedList<Integer>();
    LinkedList<Integer> Nodes = new LinkedList<Integer>();
    HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();
    ArrayList<LinkedList<Integer>> adj = new ArrayList<LinkedList<Integer>>();
    ArrayList<LinkedList<Integer>> tadj = new ArrayList<LinkedList<Integer>>();
    int find_node(int u) {
        if (map.containsKey(u))
            return map.get(u);
        else {
            adj.add(new LinkedList<Integer>());
            tadj.add(new LinkedList<Integer>());
            int p = map.size();
            map.put(u, p);
            return p;
        }
    }
    void read() {
        N = kb.nextInt();
        map.clear();
        adj.clear();
        tadj.clear();
        for (int i = 0; i < N; i++) {
            int u = kb.nextInt();
            u = find_node(u);
            int c = kb.nextInt();
            for (int k = 0; k < c; k++) {
                int v = kb.nextInt();
                v = find_node(v);
                adj.get(u).add(v);
                tadj.get(v).add(u);
            }
        }
        N = map.size();
    }
    void dfs(int u) {
        if (visited[u])
            return;
        else
            visited[u] = true;
        for (int v : adj.get(u)) {
            if (!visited[v])
                dfs(v);
        }
        order.addFirst(u);
    }
    void flood_fill(int u) {
        count++;
        visited[u] = true;
        for (int v : tadj.get(u)) {
            if (!visited[v])
                flood_fill(v);
        }
    }
    void solve() {
        order.clear();
        visited = new boolean[N];
        for (int i = 0; i < N; i++)
            dfs(i);
        for (int i = 0; i < N; i++)
            visited[i] = false;
        int A = 0, B = 0;
        for (int u : order) {
            if (!visited[u]) {
                count = 0;
                flood_fill(u);
                if (count >= 4)
                    A++;
                else
                    B += count;
            }
        }
        System.out.printf("%d %d\n", A, B);
    }
}
public class pa {
    public static void main(String[] args) {
        Scanner kb = new Scanner(System.in);
        sol s = new sol(kb);
        int c = kb.nextInt();
        for (int i = 1; i <= c; i++) {
            System.out.printf("Caso#%d\n", i);
            s.read();
            s.solve();
        }
    }
}

