public class SardasKrustall {
    public static LinkedList<Set> sets;
    public static LinkedList<Edge> A;
    public static LinkedList<Edge> edges;
    public static int find(Node node) {
        for (int i = 0; i < sets.size(); i++) {
            for (int j = 0; j < sets.get(i).nodes.size(); j++) {
                if (sets.get(i).nodes.get(j).x == node.x && sets.get(i).nodes.get(j).y == node.y) {
                    return i;
                }
            }
        }
        return -1;
    }
    public static void merge(int a, int b) {
        for (int i = 0; i < sets.get(b).nodes.size(); i++) {
            sets.get(a).nodes.add(sets.get(b).nodes.get(i));
        }
        sets.remove(b);
    }
    public static void resetId() {
        for (int i = 0; i < sets.size(); i++) {
            sets.get(i).id = i;
        }
    }
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        Graph g = new Graph(input.nextInt());
        for (int i = 0; i < g.n; i++) {
            Node n = new Node(input.nextFloat(), input.nextFloat(), i);
            g.addNode(n);
        }
        A = new LinkedList<Edge>();
        edges = new LinkedList<Edge>();
        sets = new LinkedList<Set>();
        for (int i = 0; i < g.n; i++) {
            sets.add(new Set(g.nodes[i], i));
        }
        for (int i = 0; i < g.n; i++) {
            for (int j = i + 1; j < g.n; j++) {
                edges.add(new Edge(g.nodes[i], g.nodes[j]));
            }
        }
        Collections.sort(edges);
        for (Edge e : edges) {
            int a = find(e.a);
            int b = find(e.b);
            if (a != b) {
                A.addLast(e);
                merge(a, b);
            }
        }
        double result = 0.0f;
        for (Edge E : A) {
            result += E.dist;
        }
        System.out.printf("%.2f\n", result);
    }
}

import java.util.*;
class Freckles {
    static int rank = 0;
    public static void main(String[] args) {
        Scanner stdin = new Scanner(System.in);
        int N = stdin.nextInt();
        Point[] FaceMap = new Point[N];
        for (int i = 0; i < N; i++) {
            FaceMap[i] = new Point(stdin.nextDouble(), stdin.nextDouble());
        }
        DrawOnHisFace(FaceMap, N);
    }
    public static void DrawOnHisFace(Point[] face, int N) {
        int groups = N;
        PriorityQueue<Link> links = new PriorityQueue<Link>();
        for (int i = 0; i < N - 1; i++) {
            for (int i2 = i + 1; i2 < N; i2++)
                links.add(new Link(i, i2, Distance(face[i], face[i2])));
        }
        double total = 0;
        while (links.size() != 0 && groups != 1) {
            Link first = links.poll();
            Point a = face[first.a];
            Point b = face[first.b];
            rank = 0;
            Point parentA = a.FindParent();
            int rankA = rank;
            rank = 0;
            Point parentB = b.FindParent();
            int rankB = rank;
            if (parentA != parentB) {
                if (rankA > rankB)
                    parentA.UniteRoots(parentB);
                else
                    parentB.UniteRoots(parentA);
                groups--;
                total += first.d;
            }
        }
        System.out.format("%.2f\n", total);
    }
    public static double Distance(Point a, Point b) {
        double x = Math.abs(a.x - b.x);
        double y = Math.abs(a.y - b.y);
        return Math.sqrt((x * x) + (y * y));
    }
}
class Point {
    Point prev;
    double x;
    double y;
    Point(double X, double Y) {
        prev = this;
        x = X;
        y = Y;
    }
    public int compareTo(Point a) {
        if (a.x == x && a.y == y)
            return 0;
        else if (a.x > x)
            return -1;
        else
            return 1;
    }
    public Point FindParent() {
        if (prev == this)
            return this;
        else {
            Freckles.rank++;
            prev = prev.FindParent();
        }
        if (prev != this) {
            Freckles.rank++;
            Point parent = prev.FindParent();
            prev = parent;
            return parent;
        }
        return this;
    }
    public void UniteRoots(Point a) {
        a.prev = this;
    }
}
