class Stack {
    int elems;
    Node first;
    Stack() {
        elems = 0;
        first = null;
    }
    int elemsStack() {
        return (elems);
    }
    void push(int x) {
        Node no = new Node(x);
        no.setNext(first);
        first = no;
        elems++;
    }
    int pop() {
        int x = first.getValor();
        first = first.getNext();
        elems--;
        return (x);
    }
    boolean isEmpty() {
        return (first == null);
    }
    boolean elemInStack(int x) {
        Node i;
        for (i = first; i != null; i = i.getNext())
            if (i.getValor() == x)
                return (true);
        return (false);
    }
    int[] getElements() {
        int[] elements = new int[elems];
        int j;
        Node i;
        for (i = first, j = elems - 1; i != null; i = i.getNext(), j--) {
            elements[j] = i.getValor();
        }
        return (elements);
    }
    Stack getTill(int v) {
        Node nova;
        int i;
        Stack s = new Stack();
        do {
            i = this.pop();
            s.push(i);
        } while (i != v);
        return (s);
    }
    int verPosicao(int ind) {
        Node j;
        int i;
        for (i = 0, j = first; i < ind && j != null; i++, j = j.getNext());
        if (j != null)
            return (j.getValor());
        else
            return (-1);
    }
}
