                if (colour[j] == 0) {
                    colour[j] = 2;
                    DFS1(j);
                }
            colour = new int[nAlunos];
            for (int u : ftimes) {
                if (colour[u] == 0) {
                    colour[u] = 2;
                    int lenSCC = DFS2(u);
                    if (lenSCC >= 4)
                        ng++;
                    else
                        nf += lenSCC;
                }
            }
            System.out.println("Caso #" + (i + 1));
            System.out.println(ng + " " + nf);
        }
    }
