        System.out.println(nNumGroup + " " + (arVisited.length - alOnAGroup.size()));
    }
    public static void DFS(int[][] arGroups, int[] arVis, int n) {
        arVis[n]++;
        for (int i = 0; i < arGroups[n].length; i++) {
            if (arVis[i] == 0 && arGroups[n][i] != 0)
                DFS(arGroups, arVis, i);
        }
    }
    public static void DFS_Transp(int[][] arGroups, int[] arVis, ArrayList<Integer> alOnAGroup, int n) {
        arVis[n]++;
        if (arVis[n] > 1) {
            alOnAGroup.add(n);
            nCountElem++;
        }
        for (int i = 0; i < arGroups[n].length; i++) {
            if (arVis[i] < 2 && arGroups[n][i] != 0)
                DFS_Transp(arGroups, arVis, alOnAGroup, i);
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
public class Main {
    static BufferedReader stdin = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st = new StringTokenizer("");
    static String readString() throws Exception {
        while (!st.hasMoreTokens()) {
            st = new StringTokenizer(stdin.readLine());
        }
        return st.nextToken();
    }
    static int readInt() throws Exception {
        return Integer.parseInt(readString());
    }
    static double readDouble() throws Exception {
        return Double.parseDouble(readString());
    }
    public static void main(String[] args) throws Exception {
        Double total = Double.valueOf(0);
        int numberOfFreckles = readInt();
        Double[][] freckles = new Double[numberOfFreckles][2];
        int[] sets = new int[numberOfFreckles];
        for (int i = 0; i < numberOfFreckles; i++) {
            freckles[i][0] = readDouble();
            freckles[i][1] = readDouble();
            sets[i] = i;
        }
        for (int i = 1; i < numberOfFreckles; i++) {
            Double shortest = Double.MAX_VALUE;
            int s = -1;
            for (int j = 0; j < numberOfFreckles; j++) {
                s = -1;
                if (sets[i] != sets[j]) {
                    Double n = findDistance(freckles[i], freckles[j]);
                    if (n < shortest) {
                        shortest = n;
                        s = sets[j];
                    }
                }
            }
            total += shortest;
            sets[i] = s;
        }
        System.out.printf("%.2f\n", total);
    }
    private static double findDistance(Double[] f1, Double[] f2) {
        return Math.sqrt(((f1[0] - f2[0]) * (f1[0] - f2[0])) + ((f1[1] - f2[1]) * (f1[1] - f2[1])));
    }
}

