            for (j = 0; j < n; j++)
                p[i][j] = INF;
        for (i = 0; i < n; i++)
            for (j = i + 1; j < n; j++) {
                double v = (ax[i] - ax[j]) * (ax[i] - ax[j]) + (ay[i] - ay[j]) * (ay[i] - ay[j]);
                v = Math.sqrt(v);
                if (v < p[i][j])
                    p[i][j] = p[j][i] = v;
            }
