class Node implements Comparable<Node> {
    int number;
    boolean visited;
    float distance;
    Node parent;
    int chosen;
    float chosenValue;
    float posx;
    float posy;
    Node(boolean visited, int number, float distance, Node parent, int chosen, float chosenValue, float posx, float posy) {
        this.number = number;
        this.visited = visited;
        this.distance = distance;
        this.parent = parent;
        this.chosen = chosen;
        this.chosenValue = chosenValue;
        this.posx = posx;
        this.posy = posy;
    }
    @Override public int compareTo(Node x) {
        if (this.distance < x.distance)
            return -1;
        else if (this.distance > x.distance)
            return 1;
        else {
            if (this.number < x.number)
                return -1;
            else if (this.number > x.number)
                return 1;
            else
                return 0;
        }
    }
}
class Sardas {
    static Node[] array;
    static float[][] connected;
    static LinkedList<Node> list;
    static int Nnodes;
    static double total;
