        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def next_int(self):
        return int(self.next())

    def next_double(self):
        return float(self.next())


class Sarda:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.used = False
        self.dist = 999999


def prim(r, sardas, n_s, distancias):
    custo = 0.0
    r.dist = 0
    u = 0
    for i in range(n_s):
        min = 9999999
        for j in range(n_s):
            if (sardas[j].used == False) and (sardas[j].dist) < min:
                min = sardas[j].dist
                u = j
        custo += min
        sardas[u].used = True
        for v in range(n_s):
            if (sardas[v].used == False) and (distancias[u][v]) < sardas[v].dist:
                sardas[v].dist = distancias[u][v]
    return custo


def main():
    teclado = Scanner()
    n_s = teclado.next_int()
    distancias = [[0.0 for _ in range(n_s)] for _ in range(n_s)]
    sardas = [None for _ in range(n_s)]
    for i in range(n_s):
        x = teclado.next_double()
        y = teclado.next_double()
        sardas[i] = Sarda(x, y)
    for i in range(n_s):
        for j in range(i + 1, n_s):
            x1 = sardas[i].x
            x2 = sardas[j].x
            y1 = sardas[i].y
            y2 = sardas[j].y
            dist = math.sqrt(math.pow(x2 - x1, 2) + math.pow(y2 - y1, 2))
            distancias[i][j] = distancias[j][i] = dist
    mst = prim(sardas[0], sardas, n_s, distancias)
    print("%.2f" % mst)


main()

