        self.n = n
        self.nodes = [Node() for _ in range(n)]
        self.c = 0
        for i in range(n):
            self.nodes[i] = Node()

    def add_node(self, n):
        self.nodes[self.c] = n
        self.c += 1


class Set:
    def __init__(self, a, id):
        self.nodes = [a]
        self.id = id


class Edge:
    def __init__(self, a, b):
        self.a = a
        self.b = b
        self.dist = ((b.x - a.x) ** 2 + (b.y - a.y) ** 2) ** 0.5

    def compare_to(self, e):
        if self.dist < e.dist:
            return -1
        elif self.dist > e.dist:
            return 1
        return 0


sets = []
