import sys
from collections import deque


class Arco:
    def __init__(self, fim, v):
        self.no_final = fim
        self.valor = v

    def extremo_final(self):
        return self.no_final

    def valor_arco(self):
        return self.valor


class No:
    def __init__(self):
        self.adjs = deque()
        self.visitado = False


class Grafo:
    def __init__(self, n):
        self.nvs = n
        self.narcos = 0
        self.sol = 0
        self.fora = n
        self.verts = [No() for _ in range(n + 1)]
        self.stack = deque()

    def num_vertices(self):
        return self.nvs

    def num_arcos(self):
        return self.narcos

    def clean_visited(self):
        for i in range(1, self.nvs + 1):
            self.verts[i].visitado = False

    def dfs(self):
        self.clean_visited()
        self.stack = deque()
        for i in range(1, self.nvs + 1):
            if not self.verts[i].visitado:
                self.verts[i].visitado = True
                self.dfs_pushstack(i)

    def dfs_pushstack(self, c):
        li = self.verts[c].adjs
        while li:
            proximo = li.popleft().extremo_final()
            if not self.verts[proximo].visitado:
                self.verts[proximo].visitado = True
                self.dfs_pushstack(proximo)
        self.stack.appendleft(c)

    def dfs_popstack(self, stack_):
        self.stack = stack_
        while self.stack:
            c = self.stack.popleft()
            if not self.verts[c].visitado:
                self.verts[c].visitado = True
                temp = deque()
                temp.append(c)
                temp = self.dfs_scc(c, temp)
                if len(temp) > 3:
                    self.sol += 1
                    self.fora -= len(temp)

    def dfs_scc(self, c, temp):
        for arco in self.verts[c].adjs:
            proximo = arco.extremo_final()
            if not self.verts[proximo].visitado:
                self.verts[proximo].visitado = True
                temp.append(proximo)
                self.dfs_scc(proximo, temp)
        return temp

    def adjs_no(self, i):
        return self.verts[i].adjs

    def insert_new_arc(self, i, j, valor_ij):
        self.verts[i].adjs.append(Arco(j, valor_ij))
        self.narcos += 1

    def find_arc(self, i, j):
        for adj in self.adjs_no(i):
            if adj.extremo_final() == j:
                return adj
        return None


def ler_grafo(proximo):
    rede = [None, None]
    nalunos = proximo()
    rede[0] = Grafo(nalunos)
    rede[1] = Grafo(nalunos)
    for _ in range(nalunos):
        aluno = proximo()
        namigos = proximo()
        for _ in range(namigos):
            amigo = proximo()
            rede[0].insert_new_arc(aluno, amigo, 0)
            rede[1].insert_new_arc(amigo, aluno, 0)
    return rede


def main():
    dados = sys.stdin.read().split()
    idx = 0

    def proximo():
        nonlocal idx
        valor = int(dados[idx])
        idx += 1
        return valor

    ncenarios = proximo()
    for i in range(ncenarios):
        rede = ler_grafo(proximo)
        rede[0].dfs()
        rede[1].dfs_popstack(rede[0].stack)
        print("Caso #" + str(i + 1) + "\n" + str(rede[1].sol) + " " + str(rede[1].fora))


if __name__ == "__main__":
