                if point.weight[i] < aux.dist:
                    aux.dist = point.weight[i]
                    aux.father = point


def extract_min(board, n):
    min_dist = float("inf")
    p = 0
    for i in range(n):
        if i in board:
            aux = board[i]
            if aux.dist < min_dist:
                min_dist = aux.dist
                p = i
    return p


