        self.g_t = [None] * (nv + 1)
        for i in range(1, nv + 1):
            self.g[i] = None
            self.g_t[i] = None
        self.nverts = nv
        self.ngrupos = NGrupos()
        self.vvisitado = [False] * (nv + 1)
        for i in range(1, nv + 1):
            self.vvisitado[i] = False
        self.decres_t_final = []
        self.n = 0

    def inserir_ligacao(self, de, para):
        self.g[de] = VerticesAdj(para, self.g[de])
        self.g_t[para] = VerticesAdj(de, self.g_t[para])

    def numero_grupos(self):
        self.dfs_g()
        self.dfs_gt_tfinal()
        return self.ngrupos

