                self.dfs_gvisit(i)

    def dfs_gvisit(self, v):
        self.vvisitado[v] = True
        p = self.g[v]
        while p is not None:
            if not self.vvisitado[p.vertice]:
                self.dfs_gvisit(p.vertice)
            p = p.prox
        self.decres_t_final.append(v)

    def dfs_gt_tfinal(self):
        for i in range(1, self.nverts + 1):
            self.vvisitado[i] = False
        while self.decres_t_final:
            v = self.decres_t_final.pop()
            if not self.vvisitado[v]:
                self.dfs_gtvisit(v)
                if self.n < 4:
                    self.ngrupos.npmenor4 += self.n
                else:
