                self.n = 0

    def dfs_gtvisit(self, v):
        self.vvisitado[v] = True
        p = self.g_t[v]
        while p is not None:
            if not self.vvisitado[p.vertice]:
                self.dfs_gtvisit(p.vertice)
            p = p.prox
        self.n += 1


