class Pessoa:
    def __init__(self, i, n=None):
        self.id = i
        if n is not None:
            self.namigos = n
            self.amigos = [0] * self.namigos
            self.t = 0
        else:
            self.namigos = 0
            self.amigos = []
            self.t = 0
        self.visitado = False

    def pos(self):
        p = 0
        for amigo in self.amigos:
            if amigo != 0:
                p += 1
        return p


class Grafo:
    def __init__(self, n):
        self.nos = n
        self.tempo = 0
        self.ppl = [None] * (n + 1)
        self.tppl = [None] * (n + 1)
        self.ngrupos = 0
        self.nelementos = 0
        self.res = 0
        self.visitados = 0

    def criar(self, next_int):
        for i in range(1, self.nos + 1):
            self.ppl[i] = Pessoa(i)
            self.tppl[i] = Pessoa(i, self.nos)
        for i in range(self.nos):
            id_ = next_int()
            nf = next_int()
            nova = Pessoa(id_, nf)
            self.ppl[id_] = nova
            for j in range(nf):
                f = next_int()
                self.ppl[id_].amigos[j] = f

    def transpor(self):
        for i in range(1, self.nos + 1):
            for j in range(len(self.ppl[i].amigos)):
                aux = self.ppl[i].amigos[j]
                in_ = self.tppl[aux].pos()
                self.tppl[aux].amigos[in_] = i

    def dfs(self):
        for i in range(1, len(self.ppl)):
            if self.ppl[i].visitado == False:
                self.dfs_visit(i)

    def dfs_visit(self, x):
        if self.ppl[x].visitado == False:
            self.ppl[x].visitado = True
            for j in range(len(self.ppl[x].amigos)):
                self.dfs_visit(self.ppl[x].amigos[j])
            self.tempo += 1
            self.ppl[x].t = self.tempo

    def find_max(self):
        mx = -1
        indice = -1
        for i in range(1, self.nos + 1):
            if mx < self.ppl[i].t and self.tppl[i].visitado == False:
                mx = self.ppl[i].t
                indice = i
        return indice

    def dfs_t_visit(self, x):
        if self.tppl[x].visitado == False:
            self.tppl[x].visitado = True
            self.visitados += 1
            for j in range(self.tppl[x].pos()):
                self.dfs_t_visit(self.tppl[x].amigos[j])
            self.nelementos += 1

    def dfs_t(self):
        while self.visitados < self.nos:
            id_ = self.find_max()
            if self.tppl[id_].visitado == False and id_ != -1:
                self.nelementos = 0
                self.dfs_t_visit(id_)
                if self.nelementos >= 4:
                    self.ngrupos += 1
                else:
                    self.res = self.res + self.nelementos

    def print_(self):
        print(str(self.ngrupos) + " " + str(self.res))


