        self.n = n
        self.nodes = [None] * (n + 1)

    def peso(self, x, y):
        p = math.sqrt(((self.nodes[x].x - self.nodes[y].x) * (self.nodes[x].x - self.nodes[y].x)) + ((self.nodes[x].y - self.nodes[y].y) * (self.nodes[x].y - self.nodes[y].y)))
        return p

    def prim(self, v):
        q = []
        for i in range(1, self.n + 1):
            self.nodes[i].distance = sys.float_info.max
            q.append(i)
        self.nodes[v].distance = 0
        min = sys.float_info.max
        menor = 0
        while len(q) > 0:
            min = sys.float_info.max
            for i in range(1, self.n + 1):
                if i in q and self.nodes[i].distance < min:
                    min = self.nodes[i].distance
                    menor = i
            q.remove(menor)
            u = menor
            for w in self.nodes[u].adj:
                p = self.peso(u, w)
                if w in q and p < self.nodes[w].distance:
                    self.nodes[w].pai = u
                    self.nodes[w].distance = p


