        self.visited = False
        self.x = x
        self.y = y
        self.adj = []

    def add_edge(self, a):
        self.adj.append(a)


class Edge:
    def __init__(self, from_node, target):
        self.target = target
        self.from_node = from_node
        self.weight = math.sqrt(math.pow(from_node.x - target.x, 2) + math.pow(from_node.y - target.y, 2))


class Graph:
    def __init__(self):
        self.nodes = []
        self.ink = 0.0

    def add_node(self, a):
        self.nodes.append(a)

    def populate(self):
        temp = []
        temp.extend(self.nodes)
        parent = temp.pop(0)
        while len(temp) > 0:
            for a in temp:
                parent.add_edge(self.make_edge(parent, a))
                a.add_edge(self.make_edge(a, parent))
            parent = temp.pop(0)

    def make_edge(self, a, b):
        return Edge(a, b)

    def prim(self):
        aux = float("inf")
        stuff = []
        stuff.extend(self.nodes)
        edges = []
        node = None
        auxedge = None
        node = stuff.pop(0)
        node.visited = True
        while len(stuff) > 0:
            aux = float("inf")
            edges.extend(node.adj)
            for a in edges:
                if not a.target.visited:
                    if aux > a.weight:
                        aux = a.weight
                        auxedge = a
            if aux != float("inf"):
                self.ink += aux
                auxedge.target.visited = True
                node = stuff.pop(stuff.index(auxedge.target))
        return self.ink


