class Grafo:
    def __init__(self, src):
        self.grupos = 0
        self.tempos = deque()
        self.pessoas = next(src)
        self.g = [None] * (self.pessoas + 1)
        self.gt = [None] * (self.pessoas + 1)
        for i in range(1, self.pessoas + 1):
            self.g[i] = No(i)
            self.gt[i] = No(i)
        for i in range(self.pessoas):
            ptemp = next(src)
            am = next(src)
            for j in range(am):
                amactual = next(src)
                self.g[ptemp].add_no(amactual)
                self.gt[amactual].add_no(ptemp)

    def dfs(self):
        for i in range(1, self.pessoas + 1):
            if not self.g[i].visitado:
                self.dfs_visit(self.g[i])

    def dfs_visit(self, actual):
        actual.visitado = True
        for cada in actual.adj:
            if not self.g[cada].visitado:
                self.dfs_visit(self.g[cada])
        self.tempos.appendleft(actual.val)

    def contar(self):
        while self.tempos:
            agora = self.tempos.popleft()
            if not self.gt[agora].visitado:
                self.gt[agora].visitado = True
                pessoast = self.contarf(agora)
                if pessoast >= 4:
                    self.grupos += 1
                    self.pessoas -= pessoast

    def contarf(self, pai):
        contagem = 1
        self.gt[pai].visitado = True
        for adjac in self.gt[pai].adj:
            if not self.gt[adjac].visitado:
                contagem = contagem + self.contarf(adjac)
        return contagem


