import heapq

rank = 0


class Point:
    def __init__(self, x, y):
        self.prev = self
        self.x = x
        self.y = y

    def find_parent(self):
        global rank
        if self.prev is self:
            return self
        else:
            rank += 1
            self.prev = self.prev.find_parent()
        if self.prev is not self:
            rank += 1
            parent = self.prev.find_parent()
            self.prev = parent
            return parent
        return self

    def unite_roots(self, a):
        a.prev = self


class Link:
    def __init__(self, a, b, d):
        self.a = a
        self.b = b
        self.d = d

    def __lt__(self, other):
        if other.d < self.d:
            return False
        elif other.d > self.d:
            return True
        else:
            return False

    def __repr__(self):
        return "(" + str(self.a) + "," + str(self.b) + "," + str(self.d) + ")"


def distance(a, b):
    x = abs(a.x - b.x)
    y = abs(a.y - b.y)
    return math.sqrt((x * x) + (y * y))


def draw_on_his_face(face, n):
    global rank
    groups = n
    links = []
    for i in range(n - 1):
        for i2 in range(i + 1, n):
            heapq.heappush(links, Link(i, i2, distance(face[i], face[i2])))
    total = 0
    while len(links) != 0 and groups != 1:
        first = heapq.heappop(links)
        a = face[first.a]
        b = face[first.b]
        rank = 0
        parent_a = a.find_parent()
        rank_a = rank
        rank = 0
        parent_b = b.find_parent()
        rank_b = rank
        if parent_a is not parent_b:
            if rank_a > rank_b:
                parent_a.unite_roots(parent_b)
            else:
                parent_b.unite_roots(parent_a)
            groups -= 1
            total += first.d
    print("%.2f" % total)


