        self.adjs = None

    def adicionar_adj(self, n, c):
        self.adjs = Arco(n, c, self.adjs)


class Grafo:
    def __init__(self, n):
        self.nverts = 0
        self.narcos = 0
        self.verts = [None] * n

    def novo_vert(self, n):
        self.verts[n] = Vertice(n)
        self.nverts += 1

    def novo_adj(self, v, a, c):
        if self.procura_arco(v, a) == 0:
            self.verts[v].adicionar_adj(a, c)
            self.narcos += 1

    def procura_arco(self, v, d):
        aux = self.verts[v].adjs
        while aux is not None:
            if aux.prox_vert == d:
                return 1
            else:
                aux = aux.prox
        return 0


class Fila:
    def __init__(self):
        self.first = None
        self.length = 0

    def push_node(self, v):
        self.first = Fila.Node(v, self.first)
        self.length += 1

    def pop_node(self):
        aux = self.first.val
        self.first = self.first.prox
        self.length -= 1
        return aux

    def is_empty(self):
        return self.length == 0

    class Node:
        def __init__(self, v, p):
            self.val = v
            self.prox = p


class Set:
    def __init__(self, x):
        self.size = x + 1
        self.length = 0
        self.s = [0] * (x + 1)

    def insert(self, n):
        self.s[n] = 1
        self.length += 1

    def remove(self, n):
        self.s[n] = 0
        self.length -= 1

    def tamanho(self):
        return self.length

    def imprime(self):
        for i in range(1, self.size):
            if self.s[i] == 1:
                print(i)

    def is_equal(self, x):
        if self.length != x.length:
            return False
        for i in range(self.size):
            if self.s[i] != x.s[i]:
                return False
        return True

    def intersect(self, x):
        aux = Set(self.size)
        for i in range(self.size):
            if self.s[i] == 1 and x.s[i] == 1:
                aux.insert(i)
        return aux


class Lista:
    def __init__(self):
        self.first = None
        self.length = 0

    def add_node(self, n):
        if self.length == 0:
            self.first = Lista.Node(n, None)
            self.length += 1
        else:
            aux = self.first
            flag = 0
            while aux is not None:
                if aux.s.is_equal(n):
                    flag = 1
                    break
                aux = aux.prox
            if flag == 0:
                aux = Lista.Node(n, self.first)
                self.first = aux
                self.length += 1

    class Node:
        def __init__(self, n, p):
            self.s = n
            self.prox = p


def depth_first_search(g, v, n):
    lidos = [0] * (n + 1)
    stack = Fila()
    s = Set(n + 1)
    stack.push_node(v)
    s.insert(v)
    while not stack.is_empty():
        i = stack.pop_node()
        lidos[i] = 1
        if g.verts[i] is not None:
            aux = g.verts[i].adjs
            while aux is not None:
                if lidos[aux.prox_vert] == 0:
                    stack.push_node(aux.prox_vert)
                    lidos[aux.prox_vert] = 1
                    s.insert(aux.prox_vert)
                aux = aux.prox
    return s


