class UndirectedGraph:
    def __init__(self):
        self.graph = {}

    def add_node(self, node):
        if node in self.graph:
            return False
        self.graph[node] = {}
        return True

    def add_edge(self, one, two, length):
        if one not in self.graph or two not in self.graph:
            raise LookupError("Both nodes must be in the graph.")
        self.graph[one][two] = length
        self.graph[two][one] = length

    def remove_edge(self, one, two):
        if one not in self.graph or two not in self.graph:
            raise LookupError("Both nodes must be in the graph.")
        del self.graph[one][two]
        del self.graph[two][one]

    def edge_cost(self, one, two):
        if one not in self.graph or two not in self.graph:
            raise LookupError("Both nodes must be in the graph.")
        result = self.graph[one].get(two)
        if result is None:
            raise LookupError("Edge does not exist in the graph.")
        return result

    def edges_from(self, node):
        arcs = self.graph.get(node)
        if arcs is None:
            raise LookupError("Source node does not exist.")
        return arcs

    def contains_node(self, node):
        return node in self.graph

    def __iter__(self):
        return iter(self.graph)

    def size(self):
        return len(self.graph)

    def is_empty(self):
        return len(self.graph) == 0


class FibonacciHeap:
    class Entry:
        def __init__(self, elem, priority):
            self.degree = 0
            self.is_marked = False
            self.next = self
            self.prev = self
            self.parent = None
            self.child = None
            self.elem = elem
            self.priority = priority

        def get_value(self):
            return self.elem

        def set_value(self, value):
            self.elem = value

        def get_priority(self):
            return self.priority

    def __init__(self):
        self.min_entry = None
        self.count = 0

    def enqueue(self, value, priority):
        self.check_priority(priority)
        result = FibonacciHeap.Entry(value, priority)
        self.min_entry = FibonacciHeap.merge_lists(self.min_entry, result)
        self.count += 1
        return result

    def min(self):
        if self.is_empty():
            raise LookupError("Heap is empty.")
        return self.min_entry

    def is_empty(self):
        return self.min_entry is None

    def size(self):
        return self.count

    @staticmethod
    def merge(one, two):
        result = FibonacciHeap()
        result.min_entry = FibonacciHeap.merge_lists(one.min_entry, two.min_entry)
        result.count = one.count + two.count
        one.count = two.count = 0
        one.min_entry = None
        two.min_entry = None
        return result

    def dequeue_min(self):
        if self.is_empty():
            raise LookupError("Heap is empty.")
        self.count -= 1
        min_elem = self.min_entry
        if self.min_entry.next == self.min_entry:
            self.min_entry = None
        else:
            self.min_entry.prev.next = self.min_entry.next
            self.min_entry.next.prev = self.min_entry.prev
            self.min_entry = self.min_entry.next
        if min_elem.child is not None:
            curr = min_elem.child
            while True:
                curr.parent = None
                curr = curr.next
                if curr == min_elem.child:
                    break
        self.min_entry = FibonacciHeap.merge_lists(self.min_entry, min_elem.child)
        if self.min_entry is None:
            return min_elem
        tree_table = []
        to_visit = []
        curr = self.min_entry
        while len(to_visit) == 0 or to_visit[0] is not curr:
            to_visit.append(curr)
            curr = curr.next
        for curr in to_visit:
            while True:
                while curr.degree >= len(tree_table):
                    tree_table.append(None)
                if tree_table[curr.degree] is None:
                    tree_table[curr.degree] = curr
                    break
                other = tree_table[curr.degree]
                tree_table[curr.degree] = None
                if other.priority < curr.priority:
                    min_entry = other
                    max_entry = curr
                else:
                    min_entry = curr
                    max_entry = other
                max_entry.next.prev = max_entry.prev
                max_entry.prev.next = max_entry.next
                max_entry.next = max_entry.prev = max_entry
                min_entry.child = FibonacciHeap.merge_lists(min_entry.child, max_entry)
                max_entry.parent = min_entry
                max_entry.is_marked = False
                min_entry.degree += 1
                curr = min_entry
            if curr.priority <= self.min_entry.priority:
                self.min_entry = curr
        return min_elem

    def decrease_key(self, entry, new_priority):
        self.check_priority(new_priority)
        if new_priority > entry.priority:
            raise ValueError("New priority exceeds old.")
        self.decrease_key_unchecked(entry, new_priority)

    def delete(self, entry):
        self.decrease_key_unchecked(entry, float("-inf"))
        self.dequeue_min()

    def check_priority(self, priority):
        if math.isnan(priority):
            raise ValueError(str(priority) + " is invalid.")

    @staticmethod
    def merge_lists(one, two):
        if one is None and two is None:
            return None
        elif one is not None and two is None:
            return one
        elif one is None and two is not None:
            return two
        else:
            one_next = one.next
            one.next = two.next
            one.next.prev = one
            two.next = one_next
            two.next.prev = two
            return one if one.priority < two.priority else two

    def decrease_key_unchecked(self, entry, priority):
        entry.priority = priority
        if entry.parent is not None and entry.priority <= entry.parent.priority:
            self.cut_node(entry)
        if entry.priority <= self.min_entry.priority:
            self.min_entry = entry

    def cut_node(self, entry):
        entry.is_marked = False
        if entry.parent is None:
            return
        if entry.next != entry:
            entry.next.prev = entry.prev
            entry.prev.next = entry.next
        if entry.parent.child == entry:
            if entry.next != entry:
                entry.parent.child = entry.next
            else:
                entry.parent.child = None
        entry.parent.degree -= 1
        entry.prev = entry.next = entry
        self.min_entry = FibonacciHeap.merge_lists(self.min_entry, entry)
        if entry.parent.is_marked:
            self.cut_node(entry.parent)
        else:
            entry.parent.is_marked = True
        entry.parent = None


class Prim:
    @staticmethod
    def mst(graph):
        pq = FibonacciHeap()
        entries = {}
        result = UndirectedGraph()
        if graph.is_empty():
            return result
        start_node = next(iter(graph))
        result.add_node(start_node)
        Prim.add_outgoing_edges(start_node, graph, pq, result, entries)
        for i in range(graph.size() - 1):
            to_add = pq.dequeue_min().get_value()
            endpoint = Prim.min_cost_endpoint(to_add, graph, result)
            result.add_node(to_add)
            result.add_edge(to_add, endpoint, graph.edge_cost(to_add, endpoint))
            Prim.add_outgoing_edges(to_add, graph, pq, result, entries)
        return result

    @staticmethod
    def min_cost_endpoint(node, graph, result):
        endpoint = None
        least_cost = float("inf")
        for key, value in graph.edges_from(node).items():
            if not result.contains_node(key):
                continue
            if value >= least_cost:
                continue
            endpoint = key
            least_cost = value
        return endpoint

    @staticmethod
    def add_outgoing_edges(node, graph, pq, result, entries):
        for key, value in graph.edges_from(node).items():
            if result.contains_node(key):
                continue
            if key not in entries:
                entries[key] = pq.enqueue(key, value)
            elif entries[key].get_priority() > value:
                pq.decrease_key(entries[key], value)


