import sys
import math


class Edge:
    def __init__(self, u=0, v=0, cost=0):
        self.u = u
        self.v = v
        self.cost = cost

    def __lt__(self, other):
        if self.cost == other.cost:
            return False
        return self.cost < other.cost

    def __repr__(self):
        return "(" + str(self.u) + "," + str(self.v) + "," + str(self.cost) + ")"


class DisjointSet:
    def __init__(self, n):
        self.p = list(range(n))
        self.rank = [0] * n

    def find_set(self, x):
        if self.p[x] != x:
            self.p[x] = self.find_set(self.p[x])
        return self.p[x]

    def union(self, x, y):
        self.link(self.find_set(x), self.find_set(y))

    def link(self, x, y):
        if self.rank[x] > self.rank[y]:
            self.p[y] = x
        else:
            self.p[x] = y
            if self.rank[x] == self.rank[y]:
                self.rank[y] += 1


class Sol:
    def __init__(self, tokens):
        self.tokens = tokens
        self.idx = 0
        self.points = []

    def next_double(self):
        value = float(self.tokens[self.idx])
        self.idx += 1
        return value

    def distance(self, i, k):
        dx = self.points[k][0] - self.points[i][0]
        dy = self.points[k][1] - self.points[i][1]
        return math.sqrt(dx * dx + dy * dy)

    def solve(self):
        n = int(self.next_double())
        self.points = [[0.0, 0.0] for _ in range(n)]
        for i in range(n):
            self.points[i][0] = self.next_double()
            self.points[i][1] = self.next_double()
        edges = []
        for i in range(n):
            for k in range(i + 1, n):
                edges.append(Edge(i, k, self.distance(i, k)))
        edges.sort()
        s = DisjointSet(n)
        count = 0
        total = 0
        for e in edges:
            if s.find_set(e.u) != s.find_set(e.v):
                s.union(e.u, e.v)
                total += e.cost
                count += 1
                if count == n - 1:
                    break
        print("%.2f" % total)


def main():
    kb = sys.stdin.read().split()
    s = Sol(kb)
    s.solve()


main()

