class EmptyQueueException(Exception):
    pass


class Node:
    def __init__(self, v, n):
        self.val = v
        self.next = n


class Queue:
    def __init__(self):
        self.size = 0
        self.first = None
        self.last = None

    def is_empty(self):
        return (self.size == 0)

    def get_size(self):
        return self.size

    def dequeue(self):
        if self.is_empty():
            return None
        res = self.first.val
        self.first = self.first.next
        self.size -= 1
        if self.first is None:
            self.last = None
        return res

    def enqueue(self, v):
        novo = Node(v, None)
        if self.is_empty():
            self.first = novo
            self.last = novo
        else:
            self.last.next = None
            self.last.next = novo
            self.last = novo
        self.size += 1


class Nos:
    def __init__(self, ola, xl):
        self.o = ola
        self.p = xl
        self.cnt = 0
        self.time = 0

    def scc(self):
        mt = [[0] * self.p for _ in range(self.p)]
        fs = self.dfs(self.o, self.p)
        mt = self.gl(self.o, self.p)
        self.dfsl(mt, self.p, fs)

    def dfs_visitl(self, o, color, pais, h, p):
        self.cnt += 1
        color[h] = "gray"
        for a in range(p):
            if o[h][a] == 1:
                if color[a] == "white":
                    pais[a] = h
                    self.dfs_visitl(o, color, pais, a, p)
        color[h] = "black"

    def dfsl(self, oo, p, f):
        color = ["white"] * p
        pais = [0] * p
        for i in range(p):
            color[i] = "white"
        for i in range(p):
            pais[i] = 0
        filas = Queue()
        u = -1
        z = 1
        uz = 1
        while uz != 0:
            z = self.max_(p, f)
            if u != z:
                filas.enqueue(z)
                f[z] = 0
                u = z
            else:
                uz = 0
        cntg = 0
        cntf = 0
        while not filas.is_empty():
            q = filas.dequeue()
            if color[q] == "white":
                self.dfs_visitl(oo, color, pais, q, p)
                if self.cnt > 3:
                    cntg += 1
                else:
                    cntf += self.cnt
                self.cnt = 0
        print(str(cntg) + " " + str(cntf))

    def max_(self, p, f):
        mx = 0
        ind = 0
        for b in range(p):
            if mx < f[b]:
                mx = f[b]
                ind = b
        return ind

    def dfs(self, o, p):
        color = ["white"] * p
        pais = [0] * p
        d = [0] * p
        f = [0] * p
        for i in range(p):
            color[i] = "white"
        for i in range(p):
            pais[i] = 0
            f[i] = 0
            d[i] = 0
        for h in range(p):
            if color[h] == "white":
                self.dfs_visit(o, color, pais, h, d, p, f)
        return f

    def dfs_visit(self, o, color, pais, h, d, p, f):
        self.time += 1
        d[h] = self.time
        color[h] = "gray"
        for a in range(p):
            if o[h][a] == 1:
                if color[a] == "white":
                    pais[a] = h
                    self.dfs_visit(o, color, pais, a, d, p, f)
        color[h] = "black"
        self.time += 1
        f[h] = self.time

    def gl(self, matriz, r):
        matrizl = [[0] * r for _ in range(r)]
        for ii in range(r):
            for jj in range(r):
                if matriz[ii][jj] == 1:
                    matrizl[jj][ii] = 1
        return matrizl


