import sys


class Vertice:
    def __init__(self, n, ami):
        self.n_amigos = n
        self.amigos = ami
        self.index = -1
        self.lowlink = -1

    def get_n_amigos(self):
        return self.n_amigos

    def amigo(self, x):
        return self.amigos[x]


class Stack:
    def __init__(self):
        self.elems = 0
        self.first = None

    def elems_stack(self):
        return self.elems

    def push(self, x):
        no = Node(x)
        no.set_next(self.first)
        self.first = no
        self.elems += 1

    def pop(self):
        x = self.first.get_valor()
        self.first = self.first.get_next()
        self.elems -= 1
        return x

    def is_empty(self):
        return self.first is None

    def elem_in_stack(self, x):
        i = self.first
        while i is not None:
            if i.get_valor() == x:
                return True
            i = i.get_next()
        return False

    def get_elements(self):
        elements = [0] * self.elems
        j = self.elems - 1
        i = self.first
        while i is not None:
            elements[j] = i.get_valor()
            i = i.get_next()
            j -= 1
        return elements

    def get_till(self, v):
        s = Stack()
        while True:
            i = self.pop()
            s.push(i)
            if i == v:
                break
        return s


class Node:
    def __init__(self, x):
        self.valor = x
        self.next = None

    def get_valor(self):
        return self.valor

    def set_next(self, no):
