            self.ultimo = res
        else:
            self.ultimo.set_proximo(res)
            self.ultimo = res


def primeiro_nao_analisado(estado, n):
    for i in range(n):
        if not estado[i]:
            return i
    return -1


def tarjan(alunos, v, index, pilha, lista_comp):
    alunos[v].index = index
    alunos[v].lowlink = index
    index += 1
    pilha.push(v)
    n_amigos = alunos[v].get_n_amigos()
    for i in range(n_amigos):
        amigo = alunos[v].amigo(i)
        if alunos[amigo].index == -1:
            lista_comp = tarjan(alunos, amigo, index, pilha, lista_comp)
            alunos[v].lowlink = min(alunos[v].lowlink, alunos[amigo].lowlink)
        elif pilha.elem_in_stack(amigo):
            alunos[v].lowlink = min(alunos[v].lowlink, alunos[amigo].index)
    if alunos[v].lowlink == alunos[v].index:
        lista_comp.append(pilha.get_till(v))
    return lista_comp


def contagem_de_grupos(cenario, n_alunos, alunos):
    analisados = [False] * n_alunos
    pilha = Stack()
    lista_comp = []
    n_grupos4 = 0
    outros = 0
    index = 0
    while True:
        i = primeiro_nao_analisado(analisados, n_alunos)
        if i == -1:
            break
        lista_comp = tarjan(alunos, i, index, pilha, lista_comp)
        for comp in lista_comp:
            elementos_na_pilha = comp.elems_stack()
            if elementos_na_pilha >= 4:
                n_grupos4 += 1
            else:
                outros += elementos_na_pilha
            while not comp.is_empty():
                analisados[comp.pop()] = True
        lista_comp = []
    return Resultado(cenario, n_grupos4, outros)


