class UnionFind:
    def __init__(self, n):
        self.a = list(range(n))

    def find_set(self, i):
        if self.a[i] == i:
            return i
        self.a[i] = self.find_set(self.a[i])
        return self.a[i]

    def union_set(self, l, r):
        self.a[self.find_set(l)] = self.find_set(r)


