def extrair(q_list, cam):
    dist = 99999999.0
    i = 0
    index = i
    for q2 in q_list:
        i += 1
        for cami in cam:
            dist2 = math.sqrt(((cami.x - q2.x) * (cami.x - q2.x)) + ((cami.y - q2.y) * (cami.y - q2.y)))
            if dist2 < dist:
                dist = dist2
                index = i
    return index


def prim(g, r):
    r.dist = 0
    q_list = []
    caminho = []
    for n in g.v:
        q_list.append(n)
    caminho.append(r)
    while q_list:
        index = extrair(q_list, caminho)
        u = q_list.pop(index - 1)
        for adj in caminho:
            if adj is not u:
                dist = math.sqrt(((adj.x - u.x) * (adj.x - u.x)) + ((adj.y - u.y) * (adj.y - u.y)))
                if dist < u.dist:
                    u.dist = dist
                    u.pai = u
        caminho.append(u)


