import sys

tempo = 0
pilha = []
arvore = []
grupos = 0
sozinhos = 0


class Vertice:
    def __init__(self, aluno_, namigos):
        self.aluno = aluno_
        self.amigos = [0] * namigos
        self.tamigos = []
        self.namigos = 0
        self.cor = 0
        self.tempo = 0

    def adiciona_amigo(self, amigo):
        self.amigos[self.namigos] = amigo
        self.namigos += 1

    def adicionar_amigo_transposto(self, amigo):
        self.tamigos.append(amigo)


def dfs_invertido(vertices):
    global grupos, sozinhos, arvore
    grupos = 0
    sozinhos = 0
    for v in vertices:
        v.cor = 0
    while pilha:
        u = vertices[pilha.pop() - 1]
        arvore = []
        if u.cor == 0:
            arvore.append(u.aluno)
            vertices = dfs_visit_invertido(u, vertices)
        if len(arvore) >= 4:
            grupos += 1
        else:
            sozinhos = sozinhos + len(arvore)


def dfs_visit_invertido(v, vertices):
    v.cor = 1
    for amigo in v.tamigos:
        if vertices[amigo - 1].cor == 0:
            arvore.append(amigo)
            vertices = dfs_visit_invertido(vertices[amigo - 1], vertices)
    return vertices


def calcular_transposta(vertices):
    for v in vertices:
        for aluno in v.amigos:
            vertices[aluno - 1].adicionar_amigo_transposto(v.aluno)
    return vertices


def ordenar(vertices):
    for i in range(len(vertices) - 1):
        if vertices[i + 1].aluno < vertices[i].aluno:
            temp = vertices[i]
            vertices[i] = vertices[i + 1]
            vertices[i + 1] = temp
    return vertices


def dfs(vertices):
    global tempo
    for v in vertices:
        v.cor = 0
        v.tempo = 0
    tempo = 0
    for v in vertices:
        if v.cor == 0:
            vertices = dfs_visit(v, vertices)
    return vertices


def dfs_visit(v, vertices):
    global tempo, pilha
    v.cor = 1
    tempo += 1
    v.tempo = tempo
    for amigo in v.amigos:
        if vertices[amigo - 1].cor == 0:
            vertices = dfs_visit(vertices[amigo - 1], vertices)
    tempo += 1
    v.tempo = tempo
    pilha.append(v.aluno)
    return vertices


def recolher_dados(nalunos, vertices, proximo):
    for j in range(nalunos):
        id_ = proximo()
        namigos = proximo()
        vertices[j] = Vertice(id_, namigos)
        for _ in range(namigos):
            vertices[j].adiciona_amigo(proximo())
    return vertices


def main():
    dados = sys.stdin.read().split()
    idx = 0

    def proximo():
        nonlocal idx
        valor = int(dados[idx])
        idx += 1
        return valor

    ncasos = proximo()
    for i in range(1, ncasos + 1):
        nalunos = proximo()
        vertices = [None] * nalunos
        vertices = recolher_dados(nalunos, vertices, proximo)
        vertices = ordenar(vertices)
        vertices = dfs(vertices)
        vertices = calcular_transposta(vertices)
        dfs_invertido(vertices)
        print("Caso #" + str(i) + "\n" + str(grupos) + " " + str(sozinhos))


