import sys
from collections import deque


class Sol:
    def __init__(self, kb):
        self.kb = kb
        self.N = 0
        self.count = 0
        self.visited = []
        self.order = deque()
        self.nodes = []
        self.map = {}
        self.adj = []
        self.tadj = []

    def find_node(self, u):
        if u in self.map:
            return self.map[u]
        self.adj.append([])
        self.tadj.append([])
        p = len(self.map)
        self.map[u] = p
        return p

    def read(self):
        self.N = int(self.kb.next())
        self.map.clear()
        self.adj.clear()
        self.tadj.clear()
        for _ in range(self.N):
            u = self.find_node(int(self.kb.next()))
            c = int(self.kb.next())
            for _ in range(c):
                v = self.find_node(int(self.kb.next()))
                self.adj[u].append(v)
                self.tadj[v].append(u)
        self.N = len(self.map)

    def dfs(self, u):
        if self.visited[u]:
            return
        self.visited[u] = True
        for v in self.adj[u]:
            if not self.visited[v]:
                self.dfs(v)
        self.order.appendleft(u)

    def flood_fill(self, u):
        self.count += 1
        self.visited[u] = True
        for v in self.tadj[u]:
            if not self.visited[v]:
                self.flood_fill(v)

    def solve(self):
        self.order.clear()
        self.visited = [False] * self.N
        for i in range(self.N):
            self.dfs(i)
        self.visited = [False] * self.N
        a = 0
        b = 0
        for u in self.order:
            if not self.visited[u]:
                self.count = 0
                self.flood_fill(u)
                if self.count >= 4:
                    a += 1
                else:
                    b += self.count
        print("%d %d" % (a, b))


class KB:
    def __init__(self):
        self.toks = sys.stdin.read().split()
        self.i = 0

    def next(self):
        t = self.toks[self.i]
        self.i += 1
        return t


def main():
    kb = KB()
    s = Sol(kb)
    c = int(kb.next())
    for i in range(1, c + 1):
        print("Caso#%d" % i)
        s.read()
        s.solve()


