import sys


class Grafo:
    def __init__(self, v):
        self.vertices = v
        self.lista_adj = {}
        self.lista_pre = {}
        self.color = [0] * v


def main():
    stdin = sys.stdin.read().split()
    pos = 0

    def nxt():
        nonlocal pos
        t = stdin[pos]
        pos += 1
        return int(t)

    n_cenarios = nxt()
    control = 1
    while n_cenarios >= control:
        n_alunos = nxt()
        g = Grafo(n_alunos)
        while n_alunos > 0:
            temp_adj = []
            aluno = nxt()
            amigos = nxt()
            while amigos > 0:
                amigo = nxt()
                temp_adj.append(amigo)
                if amigo not in g.lista_pre:
                    g.lista_pre[amigo] = [aluno]
                else:
                    g.lista_pre[amigo].append(aluno)
                amigos -= 1
            g.lista_adj[aluno] = temp_adj
            print("Aluno: " + str(aluno) + " tem " + str(len(temp_adj)) + " amigos")
            n_alunos -= 1
        print("Caso: " + str(control))
        control += 1


if __name__ == "__main__":
    main()

import sys


class ProblemA:
    number_of_scenarios = 0
    number_of_students = 0
    pcase = 1
    inputd = ""

    @staticmethod
    def read_string():
        r = ""
        done = False
        while not done:
            ch = sys.stdin.read(1)
            if ch == "" or ch == "\n":
                done = True
            elif ch != "\r":
                r = r + ch
        return r

    @staticmethod
    def main():
        print("Input: ")
        ProblemA.inputd = ProblemA.read_string()
        data = ProblemA.inputd.split("#")
        linenumber = 0
        while linenumber < len(data):
            if linenumber == 0:
                ProblemA.number_of_scenarios = int(data[linenumber].strip())
            else:
                while ProblemA.number_of_scenarios > 0:
                    ProblemA.number_of_students = int(data[linenumber].strip())
                    n_data = [[0] * (ProblemA.number_of_students + 1) for _ in range(ProblemA.number_of_students + 1)]
                    while ProblemA.number_of_students > 0:
                        linenumber += 1
                        str_line = data[linenumber]
                        n_data = ProblemA.cratearray(str_line, n_data)
                        ProblemA.number_of_students -= 1
                    print("Caso #" + str(ProblemA.pcase))
                    ProblemA.check_connections(n_data)
                    linenumber += 1
                    ProblemA.number_of_scenarios -= 1
                    ProblemA.pcase += 1
            linenumber += 1

    @staticmethod
    def cratearray(str_line, n_data):
        temp = str_line.split(" ")
        i = int(temp[0].strip())
        for j in range(2, len(temp)):
            n_data[i][int(temp[j].strip())] = 1
        n_data[i][i] = 1
        return n_data

    @staticmethod
    def check_connections(n_data):
        n_data = ProblemA.floyd(n_data)
        ProblemA.group_searching(n_data)

    @staticmethod
    def group_searching(n_data):
        n = len(n_data)
        groups_table = [[] for _ in range(n)]
        for i in range(1, n):
            for j in range(1, n):
                if i == j:
                    continue
                else:
                    if n_data[i][j] == 1:
                        if n_data[i][j] == n_data[j][i]:
                            groups_table = ProblemA.groups_array(groups_table, i, j, "the_same")
                            n_data[j][i] = 0
                        else:
                            groups_table = ProblemA.groups_array(groups_table, i, j, "different")
        ProblemA.printresult(groups_table)

    @staticmethod
    def groups_array(array, i, j, a):
        empty = len(array[0])
        b = [0]
        if a == "the_same":
            if empty == 0:
                array[0] = ProblemA.insert_element(array[0], i, 0)
                array[0] = ProblemA.insert_element(array[0], j, 0)
            else:
                for m in range(len(array)):
                    array[m].sort()
                    indexi = ProblemA.array_search(array[m], i)
                    indexj = ProblemA.array_search(array[m], j)
                    if indexi >= 0 and indexj >= 0:
                        break
                    if indexi < 0 and indexj < 0:
                        if len(array[m]) == 0:
                            array[m] = ProblemA.insert_element(array[m], i, -(indexi + 1))
                            array[m] = ProblemA.insert_element(array[m], j, -(indexj + 1))
                            break
                        else:
                            continue
                    if indexi >= 0 and indexj < 0:
                        temp = m
                        ij = indexj
                        temp1 = 0
                        for n in range(m + 1, len(array)):
                            array[n].sort()
                            itemp = ProblemA.array_search(array[n], j)
                            if itemp >= 0:
                                array[temp] = ProblemA.merge(array[temp], array[n])
                                array[n] = b
                                temp1 = 1
                                break
                        if temp1 == 1:
                            break
                        else:
                            array[temp].sort()
                            array[temp] = ProblemA.insert_element(array[temp], j, -(ij + 1))
                            break
                    if indexi < 0 and indexj >= 0:
                        temp = m
                        ii = indexi
                        temp1 = 0
                        for n in range(m + 1, len(array)):
                            array[n].sort()
                            indexi = ProblemA.array_search(array[n], i)
                            if indexi >= 0:
                                array[temp] = ProblemA.merge(array[temp], array[n])
                                array[n] = b
                                temp1 = 1
                                break
                        if temp1 == 1:
                            break
                        else:
                            array[temp].sort()
                            array[temp] = ProblemA.insert_element(array[temp], i, -(ii + 1))
                            break
        else:
            if empty == 0:
                array[0] = ProblemA.insert_element(array[0], i, 0)
                array[1] = ProblemA.insert_element(array[1], j, 0)
            else:
                for m in range(len(array)):
                    array[m].sort()
                    indexi = ProblemA.array_search(array[m], i)
                    indexj = ProblemA.array_search(array[m], j)
                    if indexi >= 0 and indexj >= 0:
                        break
                    if indexi < 0 and indexj < 0:
                        if len(array[m]) == 0 and len(array[m + 1]) == 0:
                            array[m] = ProblemA.insert_element(array[m], i, -(indexi + 1))
                            array[m + 1] = ProblemA.insert_element(array[m + 1], j, -(indexj + 1))
                            break
                        else:
                            continue
                    if indexi >= 0 and indexj < 0:
                        ij = 0
                        temp1 = -1
                        for n in range(m + 1, len(array)):
                            if len(array[n]) == 0 and temp1 == -1:
                                temp1 = n
                            array[n].sort()
                            itemp = ProblemA.array_search(array[n], j)
                            if itemp >= 0:
                                ij = 1
                        if ij == 1:
                            break
                        else:
                            array[temp1].sort()
                            array[temp1] = ProblemA.insert_element(array[temp1], j, 0)
                            break
                    if indexi < 0 and indexj >= 0:
                        ij = 0
                        temp1 = -1
                        for n in range(m + 1, len(array)):
                            if len(array[n]) == 0 and temp1 == -1:
                                temp1 = n
                            array[n].sort()
                            itemp = ProblemA.array_search(array[n], i)
                            if itemp >= 0:
                                ij = 1
                        if ij == 1:
                            break
                        else:
                            array[temp1].sort()
                            array[temp1] = ProblemA.insert_element(array[temp1], i, 0)
                            break
        return array

    @staticmethod
    def insert_element(original, element, index):
        length = len(original)
        destination = original[:index] + [element] + original[index:]
        return destination

    @staticmethod
    def merge(array1, array2):
        return array1 + array2

    @staticmethod
    def array_search(array, val):
        low = 0
        high = len(array) - 1
        while low <= high:
            mid = (low + high) >> 1
            mid_val = array[mid]
            if mid_val < val:
                low = mid + 1
            elif mid_val > val:
                high = mid - 1
            else:
                return mid
        return -(low + 1)

    @staticmethod
    def floyd(n_data):
        n = len(n_data)
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if n_data[i][k] == 1 and n_data[k][j] == 1:
                        n_data[i][j] = 1
        return n_data

    @staticmethod
    def printresult(n_data):
        group = 0
        out = 0
        for i in range(len(n_data)):
            t1 = 0
            t2 = 0
            if len(n_data[i]) >= 4:
                group += 1
            else:
                if len(n_data[i]) == 1 or len(n_data[i]) == 0:
                    for j in range(len(n_data[i])):
                        if n_data[i][j] != 0:
                            t1 += 1
                else:
                    t2 = len(n_data[i])
            out = out + t1 + t2
        print(str(group) + " " + str(out))


if __name__ == "__main__":
    ProblemA.main()
